INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (392, 1, 'en', 0, 'Example 1', 'Displays the records in the Print Invoices layout in a new window in Preview mode and pauses the script. You can click Continue to print the invoices, or you can cancel printing in the Print dialog box because in the Print script step, the With dialog option is On. Allow User Abort is Off so that you aren''t left with an extra window open if you cancel the script.', 'Allow User Abort [Off]
New Window [Style: Floating Document; Name: "Print Invoices"; Using layout: "Print Invoices" (Invoices)]
Enter Preview Mode [Pause: On]
Print [Restore: Printer; With dialog: On]
Close Window [Current Window]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (393, 2, 'en', 0, 'Example 1', 'Commits the records in a transaction.', 'Open Transaction []
 Open Record/Request
 Set Field [ Assets::Description ; "descriptive text" ]
Commit Transaction');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (394, 3, 'en', 0, 'Example 1', 'Queues a notification without any script or buttons.', 'Configure Local Notification [Action: Queue; Name: "BeaconDetected"; Delay: 30; Title: "Beacon Detected"; Body: $beaconMessage;]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (395, 3, 'en', 1, 'Example 2', 'Clears a queued notification.', 'Configure Local Notification [Action: Clear; Name: "BeaconDetected";]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (396, 3, 'en', 2, 'Example 3', 'Queues a notification with a 10-minute delay. Each time the user clicks or taps the Snooze button, the Process Notification script runs again to send the user a reminder after 10 minutes. The following multiline parameter is passed to the Process Notification script when the user clicks or taps the Snooze button:

RemindMe
Snooze
0

If the user clicks or taps the Prepare Now button, the Process Notification script runs the Prepare Report Now script.

Process Notification script:', 'Set Variable [ $param; Value: Get ( ScriptParameter ) ]
Set Variable [ $buttonLabel ; Value: GetValue ( $param; 2 ) ]
If [ (ValueCount ( $param ) = 0) or (PatternCount ( $buttonLabel; "Snooze" ) > 0) ]
 Configure Local Notification [
 Action: Queue ; Name: "RemindMe" ; Script: "Process Notification" ;
 Delay: 600 ; Title: "Inventory Report" ; Body: "Prepare the inventory report." ;
 Button 1 Label: "Prepare Now" ; Button 2 Label: "Snooze" ;
 Button 1 Foreground: True ]
Else If [ Exact ( $buttonLabel; "Prepare Now" ) ]
 Perform Script [ Specified: From list; "Prepare Report Now"; Parameter: ]
End If');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (397, 4, 'en', 0, 'Example 1', 'Initiates reading of a single NFC tag and stops after reaching the timeout value specified in the NFC::Timeout field. After the tag is read, the data in the tag is set in the fields specified in the Parse Result sub-script, which is called from the Scan One Finished sub-script.

Main script: Scan One', 'Go to Layout [ "NFC Tag" ; Animation: None ]
Configure NFC Reading [ Action: Read ; Script: "Scan One Finished" ; Parameter: "The current date and time is " & Get ( CurrentTimestamp ) ; Timeout: NFC::Timeout ; Format result as JSON: 1 ]
Set Variable [ $scriptParam ; Value: Get ( ScriptParameter ) ]
Perform Script [ Specified: From list ; "Parse Result" ; Parameter: $scriptParam ]
Show Custom Dialog: [ "NFC Scan Finished" ; $scriptParam ]
New Record/Request
Set Field [ NFC::Text ; Get ( ScriptParameter ) ]
Set Field [ NFC::Tag ; JSONGetElement ( NFC::Text ; "payloads[0].primary" ) ]
Set Field [ NFC::PayloadCount ; JSONGetElement ( NFC::Text ; "payloadCount" ) ]
Set Field [ NFC::Result ; JSONGetElement ( NFC::Text ; "action" ) & JSONGetElement ( NFC::Text ; "error" ) ]
Set Field [ NFC::ReadTimestamp ; Get ( CurrentTimestamp ) ]
Set Field [ NFC::ID ; JSONGetElement ( NFC::Text ; "payloads[0].identifier" ) ]
Set Field [ NFC::Type ; JSONGetElement ( NFC::Text ; "payloads[0].type" ) ]
Commit Records/Requests [ With dialog: Off ]
New Record/Request
Set Field [ NFC::Text ; Get ( ScriptParameter ) ]
Set Field [ NFC::Tag ; GetValue ( NFC::Text ; 6 ) ]
Set Field [ NFC::PayloadCount ; GetValue ( NFC::Text ; 4 ) ]
Set Field [ NFC::Result ; GetValue ( NFC::Text ; 1) & GetValue ( NFC::Text ; 2 ) ]
Set Field [ NFC::ReadTimestamp ; Get ( CurrentTimestamp ) ]
Set Field [ NFC::ID ; GetValue ( NFC::Text ; 5) ]
Set Field [ NFC::Type ; GetValue ( NFC::Text ; 7) ]
Commit Records/Requests [ With dialog: Off ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (398, 4, 'en', 1, 'Example 2', 'Initiates reading of multiple tags and stops after reaching the timeout value specified in the NFC::Timeout field or if scanning is canceled. As the tags are read, the data in the tag is set in the fields specified in the Parse Result sub-script (see Example 1).

Main script: Scan Multiple', 'Configure NFC Reading [ Action: Read ; Script: "Parse Result" ; Parameter: "Scanning started at " & Get ( CurrentTimestamp ) ; Timeout: NFC::Timeout ; Continuous Reading: 1 ; Format result as JSON: 1]
Go to Layout [ "NFC Scan List"; Animation: None ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (399, 4, 'en', 2, 'Example 3', 'Initiates tag reading and attempts to open a URL if the type of the NFC record is "U," indicating the payload is a URL. Scanning stops after reaching the timeout value specified in the NFC::Timeout field or if scanning is canceled. After the tag is read, the data in the tag is set in the fields specified in the Parse Result sub-script (see Example 1), which is called from the Open from Scan sub-script.

Main script: Scan and Open', 'Configure NFC Reading [ Action: Read ; Script: "Open from Scan" ; Parameter: "Scanning started at " & Get ( CurrentTimestamp ) ; Timeout: NFC::Timeout ; Format result as JSON: 1 ]
Go to Layout [ "NFC Scan List"; Animation: None ]
Set Variable [ $scriptParam ; Value: Get ( ScriptParameter ) ]
Perform Script [ Specified: From list ; "Parse Result" ; Parameter: $scriptParam ]
Commit Records/Requests [ With dialog: Off ]
If [ NFC::Type = "U" ]
 Open URL [ With dialog: On ; NFC::Tag ]
End If');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (400, 5, 'en', 0, 'Example 1', 'Stores a simple version number to an entry named AppVersion (with no instance ID) in the current file''s persistent data store.', 'Configure Persistent Data [ AppVersion ; Value: "2.1.0" ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (401, 5, 'en', 1, 'Example 2', 'Stores multiple configuration values for an add-on using the add-on''s instance ID.', 'Set Variable [ $instanceID ; Value: "38EA3124-9CFD-4490-A634-A0A72A613145" ]
Configure Persistent Data [ com.claris.myaddon.theme ; Instance ID: $instanceID ; Value: "Dark" ]
Configure Persistent Data [ com.claris.myaddon.language ; Instance ID: $instanceID ; Value: "en" ]
Configure Persistent Data [ com.claris.myaddon.modificationdate ; Instance ID: $instanceID ; Value: Get ( CurrentTimestamp ) ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (402, 5, 'en', 2, 'Example 3', 'Deletes a specific persistent data entry by name and instance ID.', 'Set Variable [ $instanceID ; Value: "38EA3124-9CFD-4490-A634-A0A72A613145" ]
Configure Persistent Data [ com.claris.myaddon.theme ; Instance ID: $instanceID ; Delete ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (403, 6, 'en', 0, 'Example 1', 'Runs the PopArtVideo script when an iOS or iPadOS device enters or exits the range of the specified iBeacon in the Pop Art gallery.', 'Configure Region Monitor Script [Monitor: iBeacon; Name: MonitorName; Script: "PopArtVideo"; UUID: "BA37611E-FB73-4FFD-8FD3-63459D3FF280"; Major: 10; Minor: 1]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (404, 7, 'en', 0, 'Example 1', 'Performs a find. If no records are found, displays a custom dialog box. If records are found, sorts the found set.', 'Perform Find [Restore]
If [Get ( FoundCount ) = 0]
 Show Custom Dialog ["Find Records"; "No records were found."]
Else
