End If');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (405, 8, 'en', 0, 'Example 1', 'Performs a find and sorts records. If no records match the find request, displays a custom dialog box.', 'Perform Find [Restore]
