INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (407, 10, 'en', 0, 'Example 1', 'Copies the data from Customers::Work Phone to Customers::Day Contact in all records.', 'Go to Record/Request/Page [First]
