INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (408, 11, 'en', 0, 'Example 1', 'Loops through records to export files that are in container fields. Exits the loop if a record has an empty Container field.', 'Set Variable [$PATH; Value: Get ( DocumentsPath ) & Products::Container]
Go to Record/Request/Page [First]
Loop [ Flush: Always ]
 Exit Loop If [IsEmpty ( Products::Container )]
