INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (415, 14, 'en', 2, 'Example 3', 'Performs a find. If no records are found, displays a custom dialog box. If one record is found, goes to the Invoice Details layout. If more than one record is found, goes to the Invoices layout.', 'Perform Find [Restore]
If [Get (FoundCount) = 0]
