End If');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (416, 14, 'en', 3, 'Example 4', 'Performs a find. If no records are found, displays a custom dialog box so the user can run the Find Invoices script to search again. If one record is found, goes to the Invoice Details layout. If more than one record is found, goes to the Invoices layout.

Script: Find Invoices', 'Perform Find [ ]
If [Get ( FoundCount ) = 0]
 Show Custom Dialog ["No Record Found"; "No records were found. Do you want to search again?"]
 If [Get ( LastMessageChoice ) = 1]
 #Calls this script again as a sub-script
 Perform Script [Specified: From list; "Find Invoices" ; Parameter: ]
 Else
 Show All Records
 End If
Else If [Get ( FoundCount ) = 1]
 Go to Layout ["Invoice Details"]
Else
 Go to Layout ["Invoices"]
End If
Sort Records [Restore; With dialog: Off]');
