INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (433, 23, 'en', 0, 'Example 1', 'Performs a find and suppresses the error dialog box if no records were found.', 'Set Error Capture [On]
Perform Find [Restore]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (434, 23, 'en', 1, 'Example 2', 'Performs a find. If no errors occur, sorts records. If no find criteria were specified, shows all records. If no records match the find request, displays a custom dialog box.', 'Set Error Capture [On]
Perform Find [Restore]
If [Get ( LastError ) = 0]
 Sort Records [Restore; With dialog: Off]
Else If [Get ( LastError ) = 400]
 Show All Records
Else If [Get ( LastError ) = 401]
 Show Custom Dialog ["Find"; "No records were found."]
End If');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (435, 24, 'en', 0, 'Example 1', 'Turns on script error logging and adds the current values of a variable and a field to help debug a problem.', 'Set Error Logging [ On ; Custom debug info: "Index: " & $Counter & ", PrimaryKey: " & Table::PrimaryKey ]
2024-01-22 09:43:04.552 -0800 @1 Inventory.fmp12 Admin Process records [42] Read from Data File [7] 100 Index: 7, PrimaryKey: 20E190F3-67A8-4DCF-94CF-A5EA72971FFC');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (436, 25, 'en', 0, 'Example 1', 'While a script is running, animations are typically disabled. If a script causes a slide control to switch between panels, there will be no animation providing feedback to users. To call attention to the transition from panel to panel, use Set Layout Object Animation [On] to enable animation prior to switching between slide panels using the Go to Object script step.', 'Set Layout Object Animation [On]
Go to Object [Object Name: "Panel 1"]
Pause/Resume Script [Duration (seconds): .5]
Go to Object [Object Name: "Panel 2"]
Pause/Resume Script [Duration (seconds): .5]
Go to Object [Object Name: "Panel 3"]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (437, 26, 'en', 0, 'Example 1', 'Opens a transaction and tries to set the Text field and the Number field, which has validation enabled for numeric-only data. Set Field for Text succeeds. Set Field for Number fails validation and returns an error, but the transaction doesn''t automatically revert. Instead, the custom dialog is displayed, then the transaction is committed, changing only the Text field.', 'Set Revert Transaction on Error [ Off ]
Open Transaction [ ]
 Set Field [ Table::Text ; "Novel" ]
 Set Field [ Table::Number ; "It was a dark and..." ]
 If [ Get ( LastError ) > 0 ]
 Show Custom Dialog [ "Oops, something went wrong with Number." ]
 End If
Commit Transaction');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (438, 27, 'en', 0, 'Example 1', 'Creates a related record by using a local variable to copy information into a match field.', 'Set Variable [$CURRENT_CUSTOMER_ID; Value: Customers::Customer ID]
Go to Layout ["Invoice Details"]
New Record/Request
Set Field [Invoices::Customer ID; $CURRENT_CUSTOMER_ID]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (439, 27, 'en', 1, 'Example 2', 'Uses a local variable to save records as Excel or PDF files in the Documents folder.', 'Show Custom Dialog ["Save the current record as Excel or PDF?"]
If [Get ( LastMessageChoice ) = 1]
 Set Variable [$PATH; Value: Get ( DocumentsPath ) & "Invoice " & Invoice::Invoice Number & ".xlsx"]
 Save Records as Excel [Restore; With dialog: Off; "$PATH"; Current record ; Create folders: Off]
Else
 Set Variable [$PATH; Value: Get ( DocumentsPath ) & "Invoice " & Invoice::Invoice Number & ".pdf"]
 Save Records as PDF [Restore; With dialog: Off; "$PATH";
Current record ; Create folders: Off]
End If');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (440, 27, 'en', 2, 'Example 3', 'Uses global variable as a toggle to stop a script from being triggered.

Script: Go to Selected Invoice for iPad', 'Set Variable [$$SCRIPT_TRIGGER; Value: "Off"]
Go to Layout ["Invoice Details iPad"]
If [$$SCRIPT_TRIGGER = "Off"]
 Set Variable [$$SCRIPT_TRIGGER; Value: "On"]
 Exit Script [Text Result: ]
End If
Find Matching Records [Replace; Invoices::Customer Name]
Go to Record/Request/Page [First]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (441, 28, 'en', 0, 'Example 1', 'Triggers the "ExampleFlow" flow which uses the "webhook.example.com" webhook, providing JSON data, then setting the "SampleTableName:SampleFieldName" field with the result from the interaction.', 'Trigger Claris Connect Flow [ Flow: "ExampleFlow" ; URL: "https://webhook.example.com/" ; JSON Data: JSONSetElement ( "" ; "abc" ; "xyz" ; JSONString ) ; Target: SampleTableName:SampleFieldName ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (442, 29, 'en', 0, 'Example 1', 'Closes the open popover and navigates to either the "Paid" or the "Unpaid" tab of a tab control depending on the value of Invoices::Status.', 'Close Popover
Go to Object [Object name: Invoices::Status]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (443, 30, 'en', 0, 'Example 1', 'Goes to the Print invoices layout, enters Preview mode, prints, and enters Browse mode.', 'Go to Layout ["Print Invoices"]
Enter Preview Mode [Pause: Off]
Print [With dialog: Off]
Enter Browse Mode [Pause: Off]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (444, 31, 'en', 0, 'Example 1', 'Goes to the Invoice Details layout, enters Find mode, pauses for user input, and performs the find.', 'Go to Layout ["Invoice Details"]
Enter Find Mode [Pause: On]
Perform Find [ ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (445, 32, 'en', 0, 'Example 1', 'Opens the Print Invoices layout in a new window, enters Preview mode, prints, and closes the window.', 'New Window [Style: Floating Document; Using layout: "Print Invoices" (Invoices)]
Enter Preview Mode [Pause: Off]
Print [With dialog: Off]
Close Window [Current Window]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (446, 33, 'en', 0, 'Example 1', 'Goes to the Invoice Details layout, creates a record, and goes to the Summary field.', 'Go to Layout ["Invoice Details"]
New Record/Request
Go to Field [Invoices::Summary]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (447, 34, 'en', 0, 'Example 1', 'In the active window, goes to the Summary field on the Invoice Details layout.', 'Go to Layout ["Invoice Details"]
Go to Field [Invoices::Summary]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (448, 34, 'en', 1, 'Example 2', 'Checks which device is running the database and goes to the appropriate layout.', 'If [PatternCount ( Get ( ApplicationVersion ); "iPad" )]
 Go to Layout ["Customers iPad"]
Else If [PatternCount ( Get ( ApplicationVersion ); "Pro" )]
 Go to Layout ["Customers"]
Else
 Go to Layout ["Customers iPhone"]
End If
Sort Records [Restore; With dialog: Off]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (449, 34, 'en', 2, 'Example 3', 'Switches to the Contacts layout while zooming in.', 'Go to Layout ["Contacts"; Animation: Zoom In]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (450, 35, 'en', 0, 'Example 1 - Go to records in a list of values', 'Goes to the Contacts layout and displays records specified by a carriage return-delimited list of record IDs.', 'Set Variable [ $recordList ; Value: "15¶8¶23¶4¶12" ]
Go to List of Records [ List of record IDs: $recordList ; Using layout: "Contacts" (Contacts) ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (451, 35, 'en', 1, 'Example 2 - Go to records from a saved semantic find', 'The semantic find performed in Example 2 in Perform Semantic Find saved the list of records in $$result as a JSON array of objects with recordId key-value pairs. (Notice that the JSON format of the saved result of the find is compatible with that of Go to List of Records.) Later in the same FileMaker client session, this script opens a new window, goes to the same layout (Meeting Details), and displays the same found set. If unsuccessful, the script displays an error message.', 'Go to List of Records [ List of record IDs: $$result ; Using layout: "Meeting Details" (Meetings) ; New window ]

If [ Get ( LastError ) ≠ 0 ]
 Show Custom Dialog [ "Error" ; "Could not go to the specified records. Error: " & Get ( LastError ) ]
End If');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (452, 35, 'en', 2, 'Example 3 - Recreate client''s found set on host', 'Performs a find on the FileMaker client for products with low inventory (< 50), then gets the record IDs of the found set using the GetRecordIDsFromFoundSet function. The client script then calls a script on the host and passes it the list of record IDs.', 'Go to Layout [ "Products (Products) ; Animation: None ]
Enter Find Mode [ Pause: Off ]
Set Field [ Products::Inventory ; "<50" ]
Perform Find [ ]

Set Variable [ $foundSetIDs ; Value: GetRecordIDsFromFoundSet ( ValueNumberRanges ) ]

Perform Script on Server [ "Host script" ; Specified: From list ; Parameter: $foundSetIDs ; Wait for completion: On ]

Show Custom Dialog [ "Result" ; Get ( ScriptResult ) ]
Set Variable [ $recordIDs ; Get ( ScriptParameter ) ]
Go to List of Records [ List of record IDs: $recordIDs ; Using layout: "Products" (Products) ; Animation: None ]

# Process records in found set and return $result
Exit Script [ Text Result: $result ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (453, 36, 'en', 0, 'Example 1', 'Goes to the next field in the tab order unless the Status field in the current record is empty.', 'If [IsEmpty ( Invoices::Status )]
 Show Custom Dialog ["Invoice Status cannot be empty."]
Else
