INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (455, 37, 'en', 1, 'Example 2', 'Navigates to either the "Paid" tab or the "Unpaid" tab in a tab control depending on the value of Invoices::Status.', 'If [Invoices::Status = "Paid"]
