End Loop');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (459, 39, 'en', 0, 'Example 1', 'Controls field entry validation. Can be started with the OnObjectExit script trigger.', 'If [IsEmpty ( Customers::First Name )]
