INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (460, 40, 'en', 0, 'Example 1', 'Performs a find, sorts the records, and goes to the first record.', 'Perform Find [Restore]
