INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (461, 40, 'en', 1, 'Example 2', 'Goes to the record number the user enters in the custom dialog box.', 'Show Custom Dialog ["Enter the record number you want to view."; Invoices::Record Number]
