INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (462, 40, 'en', 2, 'Example 3', 'Loops through records to export files that are in the Container field. Exits the loop if a record has an empty container field.', 'Set Variable [$PATH; Value: Get ( DocumentsPath ) & Products::Container]
Go to Record/Request/Page [First]
Loop [ Flush: Always ]
