INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (493, 57, 'en', 0, 'Example 1', 'Inserts a photo taken by the iOS or iPadOS device''s back camera at Full resolution into the File Container field.', 'Insert from Device [ Products::File Container ; Type: Camera ; Camera: Back ; Resolution: Full ; Flash: Auto ]');
