INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (499, 60, 'en', 0, 'Example 1', 'Accesses a website and inserts a PDF into the Sales Report container field.', 'Insert from URL [ With dialog: Off ; Target: Customers::Sales Report ; "https://example.com/sales_report.pdf" ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (500, 60, 'en', 1, 'Example 2', 'Inserts a map showing the customer''s address in the Address Map container field.', 'Insert from URL [ With dialog: Off ; Target: Customers::Address Map ; "http://maps.google.com/maps/api/staticmap?center=" & Customers::Address & "&zoom=14&markers=" & Customers::Address & "&size=256x256&sensor=false&key=API_KEY" ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (501, 60, 'en', 2, 'Example 3', 'Inserts the HTML code for https://www.apple.com.', 'Insert from URL [ With dialog: Off ; Target: Customers::HTML Website Code ; "https://www.apple.com" ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (502, 60, 'en', 3, 'Example 4', 'Uses the cURL options --user and --upload-file to upload a file from a container field to a server using the credentials myusername and mypassword, and stores any results from the server in the variable $$results. For HTTP or HTTPS, the filename on the server will be the same as the filename in the container field.', 'Set Variable [ $file ; Value: table::container ]
Insert from URL [ With dialog: Off ; Target: $$results ;
"https://example.com/uploads" ; Verify SSL Certificates ;
cURL options: "--user myusername:mypassword --upload-file $file
 --header \"Content-type: image/png\"" ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (503, 60, 'en', 4, 'Example 5', 'Sends email via an SMTP server with a secure connection. Uses cURL options --mail-from for the sender''s address, --mail-rcpt for the recipient''s address, --upload-file for the file containing the message, and --user for the credentials to sign in to the SMTP server.', 'Set Variable [ $mail ; Value: TextEncode ( Table::Mail ; "utf-8" ; 3 ) ]
Insert from URL [ Select ; With dialog: Off ; Target: $result ;
"smtps://smtp.example.com:465" ; Verify SSL Certificates ; cURL options:
 "--mail-from sender@example.com
 --mail-rcpt recipient@example.com
 --upload-file $mail
 --user account:password" ]
From: Sender Name <sender@example.com>
To: Recipient Name <recipient@example.com>
Subject: Subject line
Content-Type: text/html; charset="utf8"
<html><body>Body of email</body></html>');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (504, 61, 'en', 0, 'Example 1', 'Goes to the File field and inserts a PDF using the relative path image:Documents/Product Description.pdf.', 'Go to Field [Products::File]
Insert PDF ["Product Description.pdf"]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (505, 62, 'en', 0, 'Example 1', 'Goes to the Picture field and inserts a picture using the relative path image:Photos/Mobile Phone.png.', 'Go to Field [Products::Picture]
Insert Picture ["Mobile Phone.png"]');
