INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (507, 63, 'en', 1, 'Example 2', 'Inserts either "Paid" or "Unpaid" depending on the value of the Payment Date field.', 'If [ IsEmpty ( Invoices::Payment Date )]
