End If');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (508, 63, 'en', 2, 'Example 3', 'Inserts "Draft" into the Status field or displays a dialog box if Status is not on the current layout.', 'Insert Text [Select; Invoices::Status; "Draft"]
