End If');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (509, 64, 'en', 0, 'Example 1', 'Finds records that have matching values in the Customer ID field, then updates all lookups in the found set based on the relationship that uses Customer ID as a match field.', 'Go to Layout ["Invoice Details"]
Find Matching Records [Replace; Invoices::Customer ID]
Relookup Field Contents [With dialog: Off; Invoices::Customer ID]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (510, 65, 'en', 0, 'Example 1', 'Assigns serial numbers to all invoices in the found set.', 'Sort Records [Restore; With dialog: On]
