INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (511, 65, 'en', 1, 'Example 2', 'Replaces the contents of the Customer ID field in all records in the found set with the contents of the current record''s Customer ID field, without updating other fields with auto-enter options.', 'Perform Find [Restore]
Replace Field Contents [With dialog: Off ; Invoices::Customer ID ; Current Contents ; Skip auto-enter options ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (512, 66, 'en', 0, 'Example 1', 'Inserts the sum of the invoices'' grand totals into the Statistics field.', 'Set Field [Customers::Statistics; Sum ( Invoices::Grand Total )]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (513, 66, 'en', 1, 'Example 2', 'Demonstrates when to use Set Field instead of Set Field By Name to simplify scripts.', '#If the target field does not change, use the Set Field script step.
Set Field [Customers::Work Phone; Credit Collection::Phone Number]
#If you use Set Field by Name with a target field that does not change,
#you must surround the target field in quotation marks so it evaluates as a literal string
#and returns the specified field name. If you do not use quotation marks,
#Set Field by Name evaluates the specified field and uses the result as the target field.
#If the result does not specify a field name, nothing happens.
Set Field by Name ["Customers::Work Phone"; Credit Collection::Phone Number]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (514, 67, 'en', 0, 'Example 1', 'Identifies the target field (National Statistics or World Statistics) based on geographical location, then enters a calculated value (the sum of all Grand Totals) in the target field.', 'Set Field by Name [If ( Customers::Country = "Japan" ; "Customers::National Statistics" ; "Customers::World Statistics" ); Sum ( Invoices::Grand Total )]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (515, 67, 'en', 1, 'Example 2', 'Demonstrates when to use Set Field By Name instead of Set Field to simplify scripts.', '#With Set Field, an If statement with multiple Else If steps is needed
#to determine which field on the Customers table to update
#with information from Credit Collection::Phone Number.
If [Credit Collection::Call Location = "Work"]
 Set Field [Customers::Work Phone; Credit Collection::Phone Number]
Else If [Credit Collection::Call Location = "Home" ]
 Set Field [Customers::Home Phone; Credit Collection::Phone Number]
Else If [Credit Collection::Call Location = "Mobile" ]
 Set Field [Customers::Mobile Phone; Credit Collection::Phone Number]
End If
#A single Set Field by Name script step can perform the same task
#by using a calculation to determine the target field.
Set Field by Name [GetFieldName ( Evaluate ( Credit Collection::Call Location & " Phone" ) ); Credit Collection::Phone Number]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (516, 68, 'en', 0, 'Example 1', 'Calculates the number of the next available invoice ID, using the Max function to return the highest value in the Invoice ID field. If an invoice ID contains non-numeric data, then the calculation would need to be more sophisticated to maintain the numeric and non-numeric data.', 'Go to Record/Request/Page [Last]
Set Next Serial Value [Invoices::Invoice ID; Max ( Invoices::Invoice ID ) + 1]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (517, 68, 'en', 1, 'Example 2', 'Sets the next serial number value in the Product ID field options after importing records. Useful if Perform auto-enter options during import is not selected in order to preserve dates and other auto-entered values.', 'Import Records [ With dialog: Off ; Table: Products ; Source: New Product Catalog.xlsx ; Worksheet: "Stock" ; Add ; Mac Roman ]
Set Next Serial Value [ Products::Product ID ; Get ( TotalRecordCount ) + 1 ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (518, 68, 'en', 2, 'Example 3', 'Prompts the user to input the next serial value.', 'Show Custom Dialog ["Set the next serial number value"; Invoices::Next Serial Value]
