INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (535, 79, 'en', 0, 'Example 1', 'Prints the current invoice if the user has the privileges to edit it.', 'Go to Layout ["Print Invoices"]
Open Record/Request
If [Get ( LastError ) = 0]
 Print [With dialog: On]
End If
Go to Layout [original layout]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (536, 79, 'en', 1, 'Example 2', 'Checks if the current user''s account access has the privilege to edit records. If not, asks if the user wants to log in to a different account.

Note This script does not run properly if it is set to run with full access privileges because this allows any account to open the record.', 'Set Error Capture [On]
Go to Layout ["Invoice Details"]
Open Record/Request
If [Get ( LastError ) = 200]
 Show Custom Dialog ["You cannot edit this record. Do you want to re-login?"]
 If [Get ( LastMessageChoice ) = 1]
 Re-Login [With dialog: On]
 Else
 Go to Layout [original layout]
 End If
End If');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (537, 80, 'en', 0, 'Example 1', 'Displays a dialog box if the current record has been modified but not committed. Gives the user the option of reverting the record.', 'If [Get ( RecordOpenState ) = 2]
 Show Custom Dialog ["This record has been modified since it was last entered."]
 #Button 1 is Commit. Button 2 is Revert.
 If [Get ( LastMessageChoice ) = 2]
 Revert Record/Request [With dialog: Off]
 End If
End If');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (538, 81, 'en', 0, 'Example 1', 'Finds and sorts records, then saves the found set as an Excel file without prompting the user.', 'Go to Layout ["Invoices"]
Perform Find [Restore]
