Save Records as Excel [With dialog: Off; "Unpaid Invoice List.xlsx"; Records being browsed ; Create folders: Off]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (539, 82, 'en', 0, 'Example 1- Format for fine-tuning is Off', 'Saves data to a JSONL file with Format for fine-tuning turned off. The Support_QA table contains customer support questions and answers about FileMaker, as well as other data.

The script goes to the Support_QA layout and shows all records. It then sets $filePath to the JSONL file to save to in the Documents directory.

Finally, the script saves all the records in the Support_QA table, with data from the Answer field identified in the assistant object in each line.', 'Go to Layout [ "Support_QA" (Support_QA) ]
Show All Records

Set Variable [ $filePath ; Value: Get(DocumentsPath) & "support-qa.jsonl" ]

Save Records as JSONL [ Format for fine-tuning: Off ; Table: "Support_QA" ; Completion Field: Support_QA::Answer ; "$filePath" ; Create folders: Off ]
{"messages": [{"role": "system","content": "<Predefined_System_Prompt>"},{"role": "user","content": "Area=Scripting, Question=How do I create a new script in FileMaker Pro?, Version=3"},{"role": "assistant","content": "Go to Scripts menu > Script Workspace, then ..."}]}');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (540, 82, 'en', 1, 'Example 2- Save as JSONL for fine-tuning', 'Using the same Support_QA table as above, this example saves data from select fields to a JSONL file to be used for fine-tuning the AI model in Example 2 for the Fine-Tune Model script step.

The script goes to the Support_QA layout and performs a find to get the desired found set. It then sets $trainingFile to the JSONL file to save to in the Documents directory.

Finally, the script saves the found set of records in the Support_QA table to a JSONL file, with data from the Question field for the User Prompt, from the Answer field for Assistant Prompt, and a text expression that includes the Version field for System Prompt.', 'Go to Layout [ "Support_QA" (Support_QA) ]
Perform Find [ Restore ]

Set Variable [ $trainingFile ; Value: Get(DocumentsPath) & "training_data.jsonl" ]

Set Variable [ $systemPrompt ; Value: "Applies to all FileMaker Pro versions starting with: " & Support_QA::Version ]

Save Records as JSONL [ Format for fine-tuning: On ; Table: "Support_QA" ; System Prompt: $systemPrompt ; User Prompt: Support_QA::Question ; Assistant Prompt: Support_QA::Answer ; "$trainingFile" ; Create folders: Off ]
{"messages":[{"content":"Applies to all FileMaker Pro versions starting with: 3","role":"system"},{"content":"How do I create a new script in FileMaker Pro?","role":"user"},{"content":"Go to Scripts menu > Script Workspace, then ...","role":"assistant"}]}');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (541, 83, 'en', 0, 'Example 1', 'Saves the current record as a snapshot link and asks where the user wants to save the snapshot link file.', 'Save Records as Snapshot Link [Current record ; Create folders: Off]');
