INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (550, 88, 'en', 1, 'Example 2', 'Performs a find, then sorts the found set. If no records were found, allows the user to modify the find request.', 'Set Error Capture [On]
