INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (553, 91, 'en', 0, 'Example 1', 'Goes to the Invoice Details layout, enters Find mode, pauses for user input, performs a find, and returns to the original layout.', 'Go to Layout ["Invoice Details"]
Enter Find Mode [Pause: On]
Perform Find [ ]
Go to Layout [original layout]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (554, 91, 'en', 1, 'Example 2', 'Goes to Find mode, sets the Date field to the current date, and performs the find. Displays the Invoice Details layout, Invoices layout, or a custom dialog box depending on how many records were found with today''s date.', 'Set Error Capture [On]
