End If');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (555, 92, 'en', 0, 'Example 1', 'Performs a quick find with the contents of the Custom Quick Find field, sorts the found set, and goes to the first record. Started by the OnObjectSave script trigger.', 'Perform Quick Find [Invoices::Custom Quick Find]
