INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (556, 92, 'en', 1, 'Example 2', 'Goes to the Invoice Details layout and performs a quick find using the text in the quick find box. If no records are found, displays a custom dialog box. Useful with a custom menu item that performs quick finds.', 'Go to Layout ["Invoice Details"]
