INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (560, 94, 'en', 1, 'Example 2', 'Demonstrates that using the Find Matching Records script step instead of Show Omitted Only can be a simpler way to create a found set of only the current record.', '#With Show Omitted Only, multiple steps are necessary
#to create a new found set, omit the current record,
#and show only the omitted record.
Show All Records
Omit Record
Show Omitted Only
#A single Find Matching Records script step can perform the same task
#when a field with unique values, such as an Invoice ID field, is specified.
Find Matching Records [Replace; Invoices::Invoice ID]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (561, 95, 'en', 0, 'Example 1', 'Goes to the Invoices layout, performs a find, sorts the records, then goes to the first record in the found set.', 'Go to Layout ["Invoices"]
