INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (594, 116, 'en', 0, 'Example 1', 'Creates an empty data file named data.txt if the path already exists.', 'Create Data File [ "data.txt" ; Create folders: Off ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (595, 116, 'en', 1, 'Example 2', 'Checks whether a file named change.log exists in the Documents folder and, if it doesn''t, creates the file. If the file can''t be created, the script displays an error code.', 'Set Error Capture [ On ]
Set Variable [ $file ; Value: Get ( DocumentsPath ) & "change.log" ]
Get File Exists [ "$file" ; Target: $fileExists ]
If [ $fileExists ]
 Show Custom Dialog [ $file & ": Already exists" ]
 Exit Script [ Text Result: ]
End If
Create Data File [ "$file" ; Create folders: Off ]
Set Variable [ $error = Get ( LastError ) ]
If [ $error = 0 ]
 Show Custom Dialog [ $file & ": Created" ]
Else
 Show Custom Dialog [ $file & ": Not created. Error code: " & $error ]
End If');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (596, 117, 'en', 0, 'Example 1', 'Deletes the change.log file.', 'Delete File [ Target file: "change.log" ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (597, 117, 'en', 1, 'Example 2', 'Deletes the change.log file. If the file doesn''t exist or another error occurs, the script displays a custom error message.', 'Set Error Capture [ On ]
Set Variable [ $file ; Value: "change.log" ]
Delete File [ Target file: $file ]
If [ Get ( LastError ) > 0 ]
 If [ Get ( LastError ) = 100 ]
 Set Variable [ $errorMessage ; Value: "The file doesn''t exist." ]
 Else
 Set Variable [ $errorMessage ; Value: "Error: " & Get ( LastError ) & ¶ & "The file was not deleted." ]
 End If
 Show Custom Dialog [ $errorMessage ]
 Exit Script [ Text Result: ]
End If
Show Custom Dialog [ "The file was deleted." ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (598, 118, 'en', 0, 'Example 1', 'Sets a variable to the current read-write position of an open file with a file ID of 2.', 'Get Data File Position [ File ID: 2 ; Target: $position]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (599, 118, 'en', 1, 'Example 2', 'Creates a file named change.log, writes the contents of the Products::Status field to the file, then displays the read-write position. If the field contains Completed, the result displayed is Current read-write position: 9, which is after the last byte that was written.', 'Set Variable [ $file ; Value: "change.log" ]
