INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (603, 120, 'en', 1, 'Example 2', 'Checks whether a file named change.log exists in the Documents folder, and if it does, displays the file size.', 'Set Variable [ $file; Value: Get ( DocumentsPath ) & "change.log" ]
