INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (606, 122, 'en', 1, 'Example 2', 'Checks whether a file named change.log exists in the Documents folder. If it doesn''t, the script creates the file, opens it, and displays the file ID.', 'Set Variable [ $file ; Value: Get ( DocumentsPath ) & "change.log" ]
