INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (610, 126, 'en', 0, 'Example 1', 'Reads the contents of an open file with a file ID of 2 and stores the data in a variable.', 'Read from Data File [ File ID: 2 ; Amount (bytes): ; Target: $variable ; Read as: Bytes ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (611, 126, 'en', 1, 'Example 2', 'Checks whether a file named change.log exists in the Documents folder. If it does, reads the first 100 UTF-8 code units into the Utilities::Log Entry text field.', 'Set Variable [ $file ; Value: Get ( DocumentsPath ) & "change.log" ]
Get File Exists [ "$file" ; Target: $fileExists ]
If [ not $fileExists ]
 Exit Script [ Text Result: ]
End If
Open Data File [ "$file" ; Target: $fileID ]
Read from Data File [ File ID: $fileID ; Amount (bytes): 100 ; Target: Utilities::Log Entry ; Read as: UTF-8 ]
Close Data File [ File ID: $fileID ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (612, 126, 'en', 2, 'Example 3', 'If the large.log file exists and is large, reads the file 64 MB at a time into a variable until the entire file is read. If the file is smaller, it reads the entire file in one read operation. Data is read into a variable for improved performance, then the data is stored in a field.', 'Set Error Capture [ On ]
Set Variable [ $k_FileMissingError ; Value: 100 ]
Set Variable [ $k_EndOfFileError ; Value: 10 ]
Set Variable [ $k_64KB ; Value: 64 * 1024 ]
Set Variable [ $k_64MB ; Value: 64 * 1024 * 1024 ]
Set Variable [ $file ; Value: "large.log" ]
Get File Exists [ "$file" ; Target : $fileExists ]
If [ $fileExists = 0 ]
 Exit Script [ Result: $k_FileMissingError ]
End If

Open Data File [ "$file" ; Target: $fileID ]

#If the file opened successfully, read the contents.
If [ Get ( LastError ) = 0 ]
 Get File Size [ "$file" ; Target: $fileSize ]

 #If the file size is greater than 64 KB, read it 64 MB at a time.
 If [ $fileSize > $k_64KB ]

 Loop [ Flush: Always ]
 #Read up to 64 MB and store it in a variable.
 Read from Data File [ File ID: $fileID ; Amount (bytes): $k_64MB ; Target: $dataChunk ; Read as: UTF-8 ]
 Set Variable [ $readError; Value:Get ( LastError ) ]

 #If the read operation was successful or if the end of the file was reached, concatenate the data read in this pass ($dataChunk) with the data read previously ($fileContents).
 If [ ( $readError = 0 ) or ( $readError = $k_EndOfFileError ) ]
 Set Variable [ $fileContents ; Value: $fileContents & $dataChunk ]
 End If

 #Exit the loop if the read operation failed or the end of the file is reached.
 Exit Loop If [ $readError ]
 End Loop

 Else
 #If the file is no larger than 64 KB, read it all at once.
 Read from Data File [ File ID: $fileID ; Target: $fileContents ; Read as: UTF-8 ]
 End If

 #Close the data file and store the contents in a field.
 Close Data File [ File ID: $fileID ]
 Set Field [ Table::Data ; $fileContents ]

End If');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (613, 127, 'en', 0, 'Example 1', 'Opens Invoices Backup, then attempts to recover the database if it is damaged.', 'Open File [Open hidden: Off ; "Invoices Backup"]
If [Get ( LastError ) = 807]
 Recover File [With dialog: Off; "Invoices Backup.fmp12"]
End If');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (614, 128, 'en', 0, 'Example 1', 'Renames the change.log file to change1.log.', 'Rename File [ Source file: "change.log" ; New name: "change1.log" ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (615, 128, 'en', 1, 'Example 2', 'Adds the current date to the end of the file named change.log if the file exists.', 'Set Variable [ $file ; Value: "change.log" ]
Get File Exists [ "$file" ; Target: $fileExists ]
If [ $fileExists ]
 Rename File [ Source file: "$file" ; New name:
 Let ( [
 filename = Left ( $file ; Length ( $file ) - 4 ) ;
 extension = Right ( $file ; 3 ) ;
 date = Get ( CurrentDate ) ;
 year = Year ( date ) ;
 month = Month ( date ) ;
 day = Day ( date )
 ];
 filename & "-" & year & "-" & month & "-" & day & "." & extension
 ) ]
End If');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (616, 129, 'en', 0, 'Example 1', 'Saves a copy or clone of the current database.', 'Show Custom Dialog ["Save a copy or empty clone of the current file?"]
If [Get ( LastMessageChoice ) = 1]
 Save a Copy as [copy of current file ; Create folders: Off]
Else
 Save a Copy as [clone (no records) ; Create folders: Off]
End If');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (617, 130, 'en', 0, 'Example 1', 'Saves a copy of the open file whose window name is Inventory to an XML file.', 'Save a Copy as XML [ Window name: "Inventory" ; Destination file: "Inventory.xml" ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (618, 130, 'en', 1, 'Example 2', 'Saves only scripts, layouts, and custom functions from the file specified by the current window to an XML file using Specify options as JSON.', 'Set Variable [ $jsonOptions ; Value:
 JSONSetElement ( "{}" ;
 [ "catalogs_included" ; JSONMakeArray (
 "ScriptCatalog LayoutCatalog CustomFunctionsCatalog" ;
 " " ; JSONString ) ; JSONArray ] ;
 [ "include_details" ; False ; JSONBoolean ] ;
 [ "split_catalogs" ; False ; JSONBoolean ] ;
 [ "standalone_binarydata" ; False ; JSONBoolean ]
 )
]

Save a Copy as XML [ Window name: ; Destination file: "MyApp_Schema.xml" ; Include details for analysis tools ; Specify options as JSON: $jsonOptions ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (619, 130, 'en', 2, 'Example 3', 'Saves scripts, layouts, and fields into separate XML files within a folder named "MyApp_SaveAsXML".', 'Set Variable [ $jsonOptions ; Value:
 JSONSetElement ( "{}" ;
 [ "catalogs_included" ; JSONMakeArray (
 "ScriptCatalog LayoutCatalog FieldCatalog" ;
 " " ; JSONString ) ; JSONArray ] ;
 [ "include_details" ; True ; JSONBoolean ] ;
 [ "split_catalogs" ; True ; JSONBoolean ]
 )
]

Save a Copy as XML [ Window name: ; Destination file: "MyApp_SaveAsXML" ; Specify options as JSON: $jsonOptions ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (620, 131, 'en', 0, 'Example 1', 'Sets the read-write position of an open file with file ID of 2 to the value stored in a variable.', 'Set Data File Position [ File ID: 2 ; New position: $position ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (621, 131, 'en', 1, 'Example 2', 'Writes the contents of the Utilities::Log Entry field to the end of the file named change.log that is in the Documents folder.', 'Set Variable [ $file ; Value: Get ( DocumentsPath ) & "change.log" ]
Get File Exists [ "$file" ; Target: $fileExists ]
If [ not $fileExists ]
 Exit Script [ Text Result: ]
End If
Get File Size [ "$file" ; Target: $fileSize ]
Open Data File [ "$file" ; Target: $fileID ]
Set Data File Position [ File ID: $fileID ; New position: $fileSize ]
Write to Data File [ File ID: $fileID ; Data source: Utilities::Log Entry ; Write as: UTF-8 ; Append line feed ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (622, 132, 'en', 0, 'Example 1', 'Guarantees that a database is hosted upon launch. Started by the OnFirstWindowOpen script trigger.', 'Show Custom Dialog ["Make this file available on the network?"]
If [Get ( LastMessageChoice ) = 1]
 Set Multi-User [On]
End If');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (623, 132, 'en', 1, 'Example 2', 'Turns network sharing on if it is off.', 'If [Get ( MultiUserState ) = 0]
 Set Multi-User [On]
End If');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (624, 133, 'en', 0, 'Example 1', 'Checks the system language before using system formats. Started by the OnFirstWindowOpen script trigger.', 'If [Get ( SystemLanguage ) = "Japanese"]
 Set Use System Formats [On]
End If');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (625, 134, 'en', 0, 'Example 1', 'Writes the contents of a variable followed by a line feed as UTF-8-encoded text to the open data file with a file ID of 2.', 'Write to Data File [ File ID: 2 ; Data source: $variable ; Write as: UTF-8 ; Append line feed ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (626, 134, 'en', 1, 'Example 2', 'Checks whether a file in the Documents folder named change.log exists, creates it if it doesn''t exist, writes data from the Activity::Transaction field to the beginning of the file, and closes the file.', 'Set Variable [ $file ; Value: Get ( DocumentsPath ) & "change.log" ]
Get File Exists [ "$file" ; Target: $fileExists ]
If [ not $fileExists ]
 Create Data File [ "$file" ; Create folders: Off ]
End If
Open Data File [ "$file" ; Target: $fileID ]
Write to Data File [ File ID: $fileID ; Data source: Activity::Transaction ; Write as: UTF-8 ; Append line feed ]
Close Data File [ File ID: $fileID ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (627, 134, 'en', 2, 'Example 3', 'Writes data from a field to a specific position in the file named dates.txt. Before the script runs, the file contains 2024-11-30 and the Table::Month field contains 12. After the script runs, the file contains 2024-12-30.', 'Open Data File [ "dates.txt" ; Target: $fileID ]
Set Data File Position [ File ID: $fileID ; New position: 5 ]
Write to Data File [ File ID: $fileID ; Data source: Table::Month ; Write as: UTF-8 ]
Close Data File [ File ID: $fileID ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (628, 135, 'en', 0, 'Example 1', 'Adds a new user account with data entry only privileges. Requires you to change the password the next time you log in to the account.', 'Add Account [ Authenticated via: FileMaker ; Account Name: "User" ; Password: "1234" ; Privilege Set: [Data Entry Only] ; Expire password ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (629, 135, 'en', 1, 'Example 2', 'Adds a new custom OAuth account with read-only privileges using the group name in the custom dialog box.', 'Show Custom Dialog ["Do you want to add account access for a new OAuth group?" ; $GroupName ]
If [ Get ( LastMessageChoice ) = 1 ]
 Add Account [ Authenticate via: Custom OAuth ; Group Name: $GroupName ; Privilege Set: [Read-Only Access] ]
End If');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (630, 135, 'en', 2, 'Example 3', 'Adds a new data entry only account unless the current user has read-only privileges. Uses the current user''s name for the new account name.', 'If [ Get ( AccountPrivilegeSetName ) ≠ "[Read-Only Access]" ]
 Add Account [ Authenticated via: FileMaker ; Account Name: Get ( UserName ) ; Password: "1234" ; Privilege Set: [Data Entry Only] ; Expire password ]
Else
 Show Custom Dialog [ "You do not have enough privileges to add an account." ]
End If');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (631, 136, 'en', 0, 'Example 1', 'Opens the Change Password dialog box every ten times the database is opened to encourage the user to change his or her password frequently. Started by the OnFirstWindowOpen script trigger.', 'Set Field [Accounts::Open Count; Accounts::Open Count + 1]
If [Accounts::Open Count = 10]
 Set Field [Accounts::Open Count; 0]
 Change Password [With dialog: On]
End If');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (632, 137, 'en', 0, 'Example 1', 'Deletes the Sales account.', 'Delete Account [Account Name: "Sales"]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (633, 137, 'en', 1, 'Example 2', 'Deletes the current account if it has full access privileges.', 'If [Get ( AccountPrivilegeSetName ) = "[Full Access]"]
 Delete Account [Account Name: Get ( AccountName )]
 Re-Login [With dialog: On]
Else
 Show Custom Dialog ["You do not have enough privileges to delete an account."]
End If');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (634, 138, 'en', 0, 'Example 1', 'Displays the contents of the Name field and prompts the user to activate an account with that name.', 'Show Custom Dialog ["Activate the " & Accounts::Name & " account?"]
If [Get ( LastMessageChoice ) = 1]
 Enable Account [Account Name: Accounts::Name; Activate]
End if');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (635, 138, 'en', 1, 'Example 2', 'Deactivates the current account and prompts the user to log in to a different account.', 'Show Custom Dialog ["Deactivate the " & Get ( AccountName ) & " account?"]
If [Get ( LastMessageChoice ) = 1]
 Enable Account [Account Name: Get ( AccountName ); Deactivate]
 Re-Login [With dialog: On]
End if');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (636, 139, 'en', 0, 'Example 1', 'Prompts the current user to re-login after deleting the specified account.

Note Because of the Delete Account step, users must have full access privileges to run this script.', 'Delete Account [ Account Name: "User" ]
Re-Login [ With dialog: On ; Current File ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (637, 139, 'en', 1, 'Example 2', 'Uses stored credentials to re-authenticate to an external FileMaker data source named Contacts without displaying a dialog box.', 'Re-Login [ With dialog: Off ; Account Name: "ReadOnly" ; Password: "••••••••" ; "Contacts" ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (638, 140, 'en', 0, 'Example 1', 'Changes the password of the Sales account. Requires you to change the password the next time you log in to the account.', 'Reset Account Password [Account Name: "Sales"; New Password: "1234"; Expire password]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (639, 140, 'en', 1, 'Example 2', 'Asks if you want to change the current account''s password. Resets the password with the contents of the Password field.', 'Show Custom Dialog ["Reset the current account password?"; Accounts::Password]
If [Get ( LastMessageChoice ) = 1]
 Reset Account Password [Account Name: Get ( AccountName ); New Password: Accounts::Password]
End If');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (640, 141, 'en', 0, 'Example 1', 'Sets up an OpenAI account named my_account with the specified API key.', 'Configure AI Account [ Account Name: "my-account" ; Model Provider: OpenAI ; API key: "sk-RZCtpWT..." ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (641, 141, 'en', 1, 'Example 2', 'Sets up an account named my_account for a custom model provider at the specified endpoint with an API key stored in a global field.', 'Configure AI Account [ Account Name: "my-account" ; Model Provider: Custom ;
Endpoint: "https://myserver.example.com/llm/v1/" ; Verify SSL Certificates ; API key: Global::API_Key ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (642, 142, 'en', 0, 'Example 1', 'Loads a vision model from the specified container field.', 'Configure Machine Learning Model [ Name: visionModel ; Operation: Vision ; From: ModelContainerField ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (643, 142, 'en', 1, 'Example 2', 'Unloads a model from memory.', 'Configure Machine Learning Model [ Name: visionModel ; Operation: Unload ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (644, 143, 'en', 0, 'Example 1', 'Configures an AI account, then configures a prompt template for how the model should present its natural language response when referenced by a Perform SQL Query by Natural Language script step. The query asks a question about data in the Contacts table, which has data in Name and Company fields.', 'Configure AI Account [ Account Name: "my-account" ; Model Provider: OpenAI ; API key: Global::API_Key ]

Configure Prompt Template [ Template Name: "whimsical" ; Model Provider: OpenAI ; Template Type: SQL Query ; Natural Language Prompt: "The answer should be returned in plain text, not in JSON.¶ Respond in a light, whimsical tone." ]

Go to Layout [ "Contacts" (Contacts) ; Animation: None ]

Perform SQL Query by Natural Language [ Account Name: "my-account" ; Model: Global::ModelName ; Prompt: "Which company does Alea work for?" ; Options specified: From list ; Action: Query ; Data Tables: From list ; Tables... ; Stream ; Prompt Template Name: "whimsical" ; Response Target: Contacts::Response ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (645, 143, 'en', 1, 'Example 2', 'Configures an AI account, then configures a prompt template with extra information about how to find exact matches in a find request when referenced by a Perform Find by Natural Language script step. Adds to the predefined value for Find Request Prompt a rule for how to specify an exact match for an entire field using == (the first part of the predefined prompt is omitted for brevity) The prompt in the Perform Find by Natural Language script step asks for an exact match and returns the find request as JSON in the Response field.', 'Configure AI Account [ Account Name: "my-account" ; Model Provider: OpenAI ; API key: Global::API_Key ]

Configure Prompt Template [ Template Name: "find-exact" ; Model Provider: OpenAI ; Template Type: Find Request ; Find Request Prompt: "...10. To find items that match the entire fieldX value exactly, use this format: { \"fieldX\": \"==\" }" ]

Go to Layout [ "Contacts" (Contacts) ; Animation: None ]

Perform Find by Natural Language [ Account Name: "my-account" ; Model: Global::ModelName ; Prompt: "Find contacts whose name is exactly Alea" ; Get: Find Request as JSON ; Response Target: Contacts::Response ; Prompt Template Name: "find-exact" ]
{"layouts":"Contacts","query":[{"Contacts::Name":"==Alea"}],"sort":[]}');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (646, 144, 'en', 0, 'Example 1', 'Sets up a RAG account named my-rag-account with a local endpoint.', 'Configure RAG Account [ RAG Account Name: "my-rag-account" ; Endpoint: "https://myserver.example.com/llm/v1/" ; API Key: "eyJhb..." ; Verify SSL Certificates]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (647, 144, 'en', 1, 'Example 2', 'Sets up a RAG account for a production environment with a remote endpoint and API key stored in a global field.', 'Configure RAG Account [ RAG Account Name: "my-rag-account" ; Endpoint: "https://myserver.example.com/llm/v1/" ; API Key: Global::RAG_API_Key ; Verify SSL Certificates ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (648, 145, 'en', 0, 'Example 1 - Train a basic model', 'Trains a basic regression model to predict house prices based on square footage, number of bedrooms, and age of the house using the default Random Forest parameters.

In the Properties table, the Features field contains JSON arrays like [1200, 3, 15] representing square footage, bedrooms, and age, while the Price field contains the corresponding house price. After this script step runs, the model is in memory and can be used in the current FileMaker session by the PredictFromModel function by referencing the model name "HousePriceModel."

Because the model hasn''t been saved in this example, the model won''t be available after the current session ends.', 'Go to Layout [ "Properties" (Properties) ; Animation: None ]

Configure Regression Model [ Action: Train ; Model Name: "HousePriceModel" ; Algorithm: Random Forest ; Training Vectors Field: Properties::Features ; Training Target Field: Properties::Price ; Skip empty or invalid records ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (649, 145, 'en', 1, 'Example 2 - Get embedding vectors and train a model', 'Trains a regression model to predict a star rating (1 to 5) based on the text of a customer''s review.

The training data is in the Reviews table and consists of ReviewText (a text field containing the customer''s review) and Rating (a number field containing the star rating that the customer chose). After the script configures an AI account for Claris AI Model Server, it uses that account to insert text embedding vectors in the ReviewEmbedding container field based on data in the ReviewText field.

Then the script trains the regression model, naming it "ReviewModel" and using the training vectors in ReviewEmbedding, the target values in the Rating field, and custom parameters. When training is complete, the model is saved in the global container field ReviewModel.', 'Configure AI Account [ Account Name: "AI_Model_Server" ; Model Provider: Custom ; Endpoint: "https://myserver.example.com/llm/v1/" ; Verify SSL Certificates ; API key: Global::API_Key ]

Go to Layout [ "Reviews" (Reviews) ]

Insert Embedding in Found Set [ Account Name: "AI_Model_Server" ; Embedding Model: "all-MiniLM-L12-v2" ; Source Field: Reviews::ReviewText ; Target Field: Reviews::ReviewEmbedding ; Continue on error ; Show summary ]

Set Variable [ $parameters ; Value:
 Let ( [
 json = "{}" ;
 json = JSONSetElement ( json; "numTrees"; 15; JSONNumber ) ;
 json = JSONSetElement ( json; "maxDepth"; 15; JSONNumber ) ;
 json = JSONSetElement ( json; "minSamplesSplit"; 3; JSONNumber ) ;
 json = JSONSetElement ( json; "numFeatures"; 1000; JSONNumber ) ;
 json = JSONSetElement ( json; "maxFeatures"; 0; JSONNumber )
 ] ;
 json
 )
]

Configure Regression Model [ Action: Train Model ; Model Name: "ReviewModel" ; Algorithm: Random Forest ; Training Vectors Field: Reviews::ReviewEmbedding ; Training Target Field: Reviews::Rating ; Skip empty or invalid records ; Parameters: $parameters ; Save Model To: Reviews::ReviewModel ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (650, 145, 'en', 2, 'Example 3 - Calculate mean squared error', 'Calculates the mean squared error to assess the quality of a trained regression model (see Notes).

The script goes to the Reviews layout containing the training data used in Example 2, shows all records, zeroes out the $squaredLossSum variable, goes to the first record, then loads the previously saved model and names it "ReviewModel."

In the loop, for each record, the difference between the value predicted by the model using the PredictFromModel function and the actual value in the Rating field is squared and added to $squaredLossSum.

After looping through all records, the MSE value is calculated by dividing $squaredLossSum by the number of samples (the number of records in the training data set) and displayed in a dialog. When done, the script unloads the model from memory.', 'Go to Layout [ "Reviews" (Reviews) ]
Show All Records
Set Variable [ $squaredLossSum; Value: 0 ]

Configure Regression Model [ Action: Load Model ; Model Name: "ReviewModel" ; Load Model From: Reviews::ReviewModel ]

Go to Record/Request/Page [ First ]
Loop [ Flush: Always ]
 Set Variable [ $loss; Value: Reviews::Rating - PredictFromModel ( "ReviewModel" ; Reviews::ReviewEmbedding ) ]
 Set Variable [ $squaredLoss ; Value: $loss^2 ]
 Set Variable [ $squaredLossSum ; Value: $squaredLossSum + $squaredLoss ]
 Go to Record/Request/Page [ Next ; Exit after last: On ]
End Loop

Show Custom Dialog [ "MSE Value" ; $squaredLossSum / Get ( FoundCount ) ]

Configure Regression Model [ Action: Unload Model ; Model Name: "ReviewModel" ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (651, 146, 'en', 0, 'Example 1 - Basic fine-tuning using table data', 'Fine-tunes an OpenAI model with data from a table. The script configures an AI account for OpenAI and goes to the Support_QA layout. The Support_QA table contains Question and Answer fields among others. The script performs a find to get the desired found set, then sends data from those records to fine-tune a GPT-4.1 model, specifying the Answer field for Completion Field (data from all other fields is sent as the user prompt).', 'Configure AI Account [ Account Name: "my-account" ; Model Provider: OpenAI ; API key: Global::OpenAI_API_Key ]

Go to Layout [ "Support_QA" (Support_QA) ]

Perform Find [ Restore ]

Fine-Tune Model [ Account Name: "my-account" ; Base Model: "gpt-4.1-2025-04-14" ; Training Data: Table ; "Support_QA" ; Completion Field: Support_QA::Answer ; Response Target: $$responseTarget ]
Generate Response from Model [ Account Name: "my-account" ; Model: "ft:gpt-4o-mini-2024-07-18:my-org::LBNO71Qq" ; User Prompt: $question ; Agentic mode ; Response: $$response ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (652, 146, 'en', 1, 'Example 2 - Fine-tuning using a JSONL file', 'Fine-tunes a model on the AI model server by sending the JSONL file created in Example 2 for the Save Records as JSONL script step. The script configures an AI account for and sets the $trainingFile variable to the path for the JSONL file in the Documents folder.

The script then sets the $parameters variable to a JSON object containing the key-value pairs to use for fine-tuning parameters, including setting the root name to give the fine-tuned model.

Finally, the script sends the JSONL file specified by $trainingFile to the AI model server, indicating the base model to be fine-tuned, the parameters to use, and the $response variable to store the response. To have the full fine-tuned model name available to use later, the script gets the name from $response and stores it in a global field.', 'Configure AI Account [ Account Name: "AI_Model_Server" ; Model Provider: Custom ; Endpoint: "https://myserver.example.com/llm/v1/" ; API key: Global::Fine_Tuning_API_Key ; Verify SSL Certificates ]

Set Variable [ $trainingFile ; Value: Get(DocumentsPath) & "training_data.jsonl" ]

Set Variable [ $parameters ; Value:
 Let ( [
 json = "{}" ;
 json = JSONSetElement ( json; "max_steps"; 1500; JSONString ) ;
 json = JSONSetElement ( json; "learning_rate"; 1e-4; JSONString ) ;
 json = JSONSetElement ( json; "batch_size"; 2; JSONString ) ;
 json = JSONSetElement ( json; "fine_tuned_model_name"; "product-expert-v2" ; JSONString )
 ] ;
 json
 )
]

Fine-Tune Model [ Account Name: "AI_Model_Server" ; Base Model: "google/codegemma-7b-it" ; Training Data: File ; "$trainingFile" ; Response Target: $responseTarget ; Fine-Tune Parameters: $parameters ]

Set Field [ Global::Fine_Tuned_Model ; JSONGetElement ( $responseTarget ; "result.fine_tuned_model" ) ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (653, 147, 'en', 0, 'Example 1', 'Configures an AI account, goes to the Contacts layout, then displays a dialog for the user to enter a question. The Generate Response from Model script step then sends the prompt and the recent message history to the model and streams the result to the Response field. For a simple question-and-answer interaction like this, Agentic mode is not selected. To maintain context with the model during the current FileMaker client session, the script step stores the most recent 10 messages in the $$Messages global variable via the Save Message History To option. Via the Messages option, the script step sends the value of the $$Messages variable to the model when this script is run subsequently in the same session. Because the Tool Definitions option isn''t used, the model won''t be able to answer questions about your data.', 'Configure AI Account [ Account Name: "my-account" ; Model Provider: OpenAI ; API key: Global::API_Key ]

Go to Layout [ "Contacts" (Contacts) ]

Show Custom Dialog [ "Enter a question" ; $UserPrompt ]

Generate Response from Model [ Account Name: "my-account" ; Model: Global::ModelName ; User Prompt: $UserPrompt ; Response: Contacts::Response ; Messages: $$Messages ; Save Message History To: $$Messages ; Message History Count: 10 ; Stream ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (654, 147, 'en', 1, 'Example 2', 'Configures an AI account, goes to the Contacts layout, then sends a prompt asking about data in the Contacts table to the model, which uses tools to generate a response. Because up to 10 messages are saved via $$Messages to the Messages global field, context is preserved across FileMaker client sessions.', 'Configure AI Account [ Account Name: "my-account" ; Model Provider: OpenAI ; API key: Global::API_Key ]

Go to Layout [ "Contacts" (Contacts) ]

Set Variable [ $Instructions ; Value: "You are a helpful assistant that can query database information. Always provide clear, formatted responses." ]

Set Variable [ $UserPrompt ; "How many contacts do we have from Acme Anvils, and what are their names and email addresses? Add an asterisk after the contacts who are in a city where we have a sales office." ]

Generate Response from Model [ Account Name: "my-account" ; Model: Global::ModelName ; User Prompt: $UserPrompt ; Response: Contacts::Response ; Tool Calls from Model: $$ToolCalls ; Instructions: $Instructions ; Messages: Global::Messages ; Save Message History To: $$Messages ; Message History Count: 10 ; Include tool calls in message history ; Tool Definitions: Global::ToolDefinitions ; Stream ]

Set Field [ Global::Messages ; $$Messages ]
[
 {
 "function": {
 "description": "Respond to the user''s questions by executing the appropriate SQL query using this function. Strictly follow these rules:\r 1. The input should be a fully formed SQL query.\r 2. Perform separate SQL instead of one nested SQL.\r 3. Escaping special characters for SQL query.\r 4. If the result of the toolCall is a raw string that reads ''empty'' or ''null'', the answer should contain the quoted raw string, which is case sensitive.\r 5. Convert the user''s request into an SQL query using standard SQL syntax only. Ensure that table names and field names match exactly as they appear in the database schema.",
 "name": "execute_sql",
 "parameters": {
 "properties": {
 "sql_query": {
 "description": "Generate a fully formed SQL query based on following rules:\r 1. Enclose all table and field names in double quotes.\r 2. Format dates as \"DATE ''YYYY-MM-DD''\", times as \"TIME ''HH:MM:SS''\" and timestamps as \"TIMESTAMP ''YYYY-MM-DD HH:MM:SS''\".\r 3. Return queries in plain text (not JSON).\r 4. Use \"FETCH FIRST n ROW ONLY\" instead of \"LIMIT\".\r 5. Support single queries only.\r 6. No semicolon is needed at the end of SQL query.\r 7. Don''t generate nested SQL queries.\r 8. Use \"LIKE\" instead of \"ILIKE\".\r 9. Keep all comparisons case-sensitive.\r 10. Do not include fields that are not included in the question.\r 11. Use unquoted ROWID in queries.\r 12. Only utilize the following database schema:\rCREATE TABLE \"Contacts\" (\r\"First Name\" varchar(255),\r\"Last Name\" varchar(255),\r\"Email\" varchar(255),\r\r\"City\" varchar(255),\r\"Company\" varchar(255)\r);\r\r",
 "type": "string"
 }
 },
 "type": "object",
 "required": ["sql_query"]
 }
 },
 "type": "function"
 },
 {
 "function": {
 "description": "Check whether our company has a sales office in a specified city. If it does, this function returns ''yes''; otherwise, it returns ''no''.",
 "name": "CityHasSalesOffice",
 "parameters": {
 "properties": {
 "city": {
 "description": "The name of a city",
 "type": "string"
 }
 },
 "type": "object",
 "required": ["city"]
 }
 },
 "type": "function"
 }
]
We have 4 contacts from Acme Anvils. Here are their names and email addresses, with an asterisk (*) after those who are in a city where we have a sales office:

1. Alea Marks: aleamarks165@example.com (Onitsha)
2. Kelly Holden: kellyholden1361@example.com (Berlin) *
3. Kelsey Cummings: kelseycummings1396@example.com (Saint-Malo)
4. Kuame Savage: kuamesavage7146@example.com (Wanneroo)
[
