INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (655, 148, 'en', 0, 'Example 1', 'Configures an AI account, goes to the Meeting Details layout, then uses the model to get embedding vectors for the text in the Meetings::Note field in the current record and stores it as binary data in the Meetings::Note_Embedding container field.', 'Configure AI Account [ Account Name: "my-account" ; Model Provider: OpenAI ; API key: "sk-RZCtpWT..." ]

Go to Layout [ "Meeting Details" (Meetings) ; Animation: None ]

Insert Embedding [ Account Name: "my-account" ; Embedding Model: "text-embedding-3-small" ; Input: Meetings::Note ; Target: Meetings::Note_Embedding ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (656, 149, 'en', 0, 'Example 1', 'Configures an AI account, goes to the Meeting Details layout, shows all records, then gets embedding vectors for the text in the Meetings::Note field and stores it as binary data in the Meetings::Note_Embedding container field. Because the Replace target contents option is on, Meetings::Note_Embedding is updated even if it already contains data.', 'Configure AI Account [ Account Name: "my-account" ; Model Provider: OpenAI ; API key: "sk-RZCtpWT..." ]

Go to Layout [ "Meeting Details" (Meetings) ; Animation: None ]
Show All Records

Insert Embedding in Found Set [ Account Name: "my-account" ; Embedding Model: "text-embedding-3-small" ; Source Field: Meetings::Note ; Target Field: Meetings::Note_Embedding ; Replace target contents ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (657, 149, 'en', 1, 'Example 2', 'Configures an AI account, goes to the Meeting Details layout, then finds the records in which the Meetings::Title field contains "Status." For this found set, gets embedding vectors for the text in the Meetings::Note field and stores it as binary data in the Meetings::Note_Embedding container field, if there''s no data already present (Replace target contents is off). Also sets the Parameters option to increase the records per call, number of retries, and time between retries and to lower the token limit.', 'Configure AI Account [ Account Name: "my-account" ; Model Provider: OpenAI ; API key: "sk-RZCtpWT..." ]

Go to Layout [ "Meeting Details" (Meetings) ; Animation: None ]
Enter Find Mode [ Pause: Off ]
Set Field [ Meetings::Status ; "Done" ]
Perform Find [ ]

Insert Embedding in Found Set [ Account Name: "my-account" ; Embedding Model: "text-embedding-3-small" ; Source Field: Meetings::Note ; Target Field: Meetings::Note_Embedding ;
Parameters: JSONSetElement ( "" ;
 ["MaxRecPerCall" ; 40 ; JSONNumber] ;
 ["MaxRetryPerWorker" ; 10 ; JSONNumber] ;
 ["MaxWaitPerRetry" ; 300000 ; JSONNumber] ;
 ["TruncateTokenLimit" ; 4000 ; JSONNumber] ;
 ["TruncateEnabled" ; 1 ; JSONNumber]
) ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (658, 149, 'en', 2, 'Example 3', 'Configures an AI account for a custom model provider, goes to the Meeting Details layout, shows all records, then for each record uses an image embedding model to get embedding vectors for the image in the Meetings::Image container field and stores it as binary data in the Meetings::Image_Embedding container field. If an error is encountered when getting embedding vectors for a record, the script step continues to the next record.', 'Configure AI Account [ Account Name: "my-account" ; Model Provider: Custom ; Endpoint: "https://myserver.example.com/llm/v1/" ; Verify SSL Certificates ; API key: Global::API_Key ]

Go to Layout [ "Meeting Details" (Meetings) ; Animation: None ]
Show All Records

Insert Embedding in Found Set [ Account Name: "my-account" ; Embedding Model: Global::ModelName ; Source Field: Meetings::Image ; Target Field: Meetings::Image_Embedding ; Replace target contents ; Continue on error ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (659, 150, 'en', 0, 'Example 1 - Generate caption for photo in current record', 'Configures an AI account for Claris AI Model Server. The script then goes to the Products layout, uses the model to generate a caption for the image in the Products::Photo field in the current record, and stores it in the Products::Caption text field.', 'Configure AI Account [ Account Name: "my-account" ; Model Provider: Custom ; Endpoint: "https://my-server.example.com/llm/v1/" ; Verify SSL Certificates ; API key: Global::API_Key ]

Go to Layout [ "Products" (Products) ; Animation: None ]

Insert Image Caption [ Account Name: "my-account" ; Model: "Salesforce/blip2-opt-2.7b" ; Input: Products::Photo ; Target: Products::Caption ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (660, 151, 'en', 0, 'Example 1 - Generate captions for all photos', 'Configures an AI account for Claris AI Model Server, goes to the Products layout, shows all records, then generates captions for the images in the Products::Image field and stores them in the Products::Caption text field. Because the Replace target contents option is on, Products::Caption is updated even if it already contains data.', 'Configure AI Account [ Account Name: "my-account" ; Model Provider: Custom ; Endpoint: "https://my-server.example.com/llm/v1/" ; Verify SSL Certificates ; API key: Global::API_Key ]

Go to Layout [ "Products" (Products) ; Animation: None ]
Show All Records

Insert Image Captions in Found Set [ Account Name: "my-account" ; Model: "Salesforce/blip2-opt-2.7b" ; Source Field: Products::Photo ; Target Field: Products::Caption ; Replace target contents ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (661, 151, 'en', 1, 'Example 2 - Generate missing captions for photos in found set', 'Configures an AI account for Claris AI Model Server, goes to the Product layout, then finds the records in which the Products::Category field contains "Hand Tools." For this found set, generates captions for the images in the Products::Photo field and stores them in the Products::Caption text field, if there''s no data already present (Replace target contents is off). If an error is encountered when generating a caption for a record, the script step continues to the next record.', 'Configure AI Account [ Account Name: "my-account" ; Model Provider: Custom ; Endpoint: "https://my-server.example.com/llm/v1/" ; Verify SSL Certificates ; API key: Global::API_Key ]

Go to Layout [ "Products" (Products) ; Animation: None ]
Enter Find Mode [ Pause: Off ]
Set Field [ Products::Category ; "Hand Tools" ]
Perform Find [ ]

Insert Image Captions in Found Set [ Account Name: "my-account" ; Model: "Salesforce/blip2-opt-2.7b" ; Source Field: Products::Photo ; Target Field: Products::Caption ; Continue on error ; Parameters: JSONSetElement ( "" ;
 ["MaxRecPerCall" ; 40 ; JSONNumber] ;
 ["MaxRetryPerWorker" ; 10 ; JSONNumber]
) ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (662, 152, 'en', 0, 'Example 1', 'Configures an AI account, goes to the Contacts layout, then uses this script step to search for contacts named "Alea" in the current layout. This script step sends the findable fields on the current layout and the prompt "Find contacts named Alea" to the model. The model sends back a find request (possibly a request for "Alea" in the Name field), and this script step performs the find, updating the found set in the current window.', 'Configure AI Account [ Account Name: "my-account" ; Model Provider: OpenAI ; API key: "sk-..." ]

Go to Layout [ "Contacts" (Contacts) ; Animation: None ]

Perform Find by Natural Language [ Account Name: "my-account" ; Model: Global::ModelName ; Prompt: "Find contacts named Alea" ; Get: Found Set ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (663, 152, 'en', 1, 'Example 2', 'Configures an AI account, prompts the user for a query, then performs the find and returns the data of the resulting found set as JSON in the $$FoundSetData variable. Queries are performed on the current layout.', 'Configure AI Account [ Account Name: "my-account" ; Model Provider: OpenAI ; API key: "sk-..." ]

Go to Layout [ "Products" (Products) ; Animation: None ]

Show Custom Dialog [ "Find products:" ; $$UserPrompt ]

If [ not IsEmpty ( $$UserPrompt ) ]

 Perform Find by Natural Language [ Account Name: "my-account" ; Model: Global::ModelName ; Prompt: $$UserPrompt ; Get: Found Set as JSON ; Response Target: $$FoundSetData ]

 Show Custom Dialog [ "Found Set Data:" ; JSONFormatElements ( $$FoundSetData ) ]

End If
{
