INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (664, 152, 'en', 2, 'Example 3', 'Configures an AI account, then configures a custom prompt template that uses the predefined prompt for a find request. The predefined prompt describes the JSON format for a find request and includes the following: Use the following information as context: \":context:\".

After going to the Products layout and setting the $$Today variable to a natural language phrase to use for context later, this script step substitutes the :context: constant used in the prompt template with the value of the context_prompt key in Parameters. It then sends that along with the prompt "Find records created today sorted by product name" to the model.

The model returns the find request as a JSON object in the $$FindRequestJSON variable, which you can use for debugging purposes.', 'Configure AI Account [ Account Name: "my-account" ; Model Provider: OpenAI ; API key: "sk-..." ]

Configure Prompt Template [ Template Name: "FindToday" ; Model Provider: OpenAI ; Template Type: Find Request ; Find Request Prompt: "Generate and only return a JSON layout query to perform a find request..." ]

Go to Layout [ "Products" (Products) ; Animation: None ]

Set Variable [ $$Today ; Value: "Today is " & Get ( CurrentDate ) ]

Perform Find by Natural Language [ Account Name: "my-account" ; Model: Global::ModelName ; Prompt: "Find records created today sorted by product name" ; Get: Find Request as JSON ; Parameters: JSONSetElement ( "{}" ; "context_prompt" ; $$Today ; JSONString ) ; Response Target: $$FindRequestJSON ]

Show Custom Dialog [ "Generated Find Request" ; JSONFormatElements ( $$FindRequestJSON ) ]
{
 "layouts" : "Products",
 "query" :
 [
 {
 "Products::CreationDate" : "08/27/2026"
 }
 ],
 "sort" :
 [
 {
 "fieldName" : "Products::ProductName",
 "sortOrder" : "ascend"
 }
 ]
}');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (665, 153, 'en', 0, 'Example 1 - Add text to a RAG space', 'Adds text content to a RAG space for a customer knowledge base.', 'Configure RAG Account [ RAG Account Name: "customer-support-rag-account" ; Endpoint: "https://myserver.example.com/llm/v1/" ; API key: "eyJh..." ; Verify SSL Certificates ]

Perform RAG Action [ RAG Account Name : "customer-support-rag-account" ; Space ID: "knowledge-base" ; Action: Add Data ; RAG Data: From Text ; "Customer support policies and procedures for handling returns and exchanges..." ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (666, 153, 'en', 1, 'Example 2 - Send a prompt to query a RAG space', 'Sends a prompt to query the same RAG space as in Example 1 and stores the response in a field.

The script sets up both the RAG account and the AI account to use the AI model server.

The $parameters variable includes similarity_threshold set to 0.6 to ensure only highly relevant RAG results are included, and num_top_ranked_results set to 5 to limit the context to the top 5 most relevant document chunks, overriding the defaults configured in Admin Console. It also includes CURLOPT_TIMEOUT to cancel the request after 30 seconds if there''s no response.

When it sends the prompt, the script sends the temperature and max_tokens parameters to the model for response generation and streams the response to a field.', 'Configure RAG Account [ RAG Account Name: "customer-support-rag-account" ; Endpoint: "https://myserver.example.com/llm/v1/" ; API key: Global::RAG_API_Key ; Verify SSL Certificates ]

Configure AI Account [ Account Name: "AI_Model_Server" ; Model Provider: Custom ; Endpoint: "https://myserver.example.com/llm/v1/" ; API key: Global::Text_Gen_API_Key ; Verify SSL Certificates ]

Set Variable [ $parameters ; Value:
 JSONSetElement ( "{}" ;
 [ "temperature" ; .3 ; JSONNumber ] ;
 [ "max_tokens" ; 500 ; JSONNumber ] ;
 [ "similarity_threshold" ; .6 ; JSONNumber ] ;
 [ "num_top_ranked_results" ; 5 ; JSONNumber ] ;
 [ "CURLOPT_TIMEOUT" ; 30 ; JSONNumber ]
 )
]

Perform RAG Action [ RAG Account Name: "customer-support-rag-account" ; Space ID: "knowledge-base" ; Action: Send Prompt ; Send Prompt: "What is the return policy for defective products?" ; AI Account Name: "AI_Model_Server" ; Model: Global::ModelName ; Stream: On ; Response Target: Customer_Support::AI_Response ; Parameters: $parameters ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (667, 153, 'en', 2, 'Example 3 - Add and remove a PDF file from a RAG space', 'Adds a PDF file named Policies.pdf to a RAG space, then removes it.

After configuring the RAG account to use on the AI model server, the script adds the Policies.pdf file to the RAG space by specifying its file path. Before it can remove the file, the script must find the document ID that was assigned when the file was added. The document ID is returned by Response Target and stored in $ragAddResponse. For example:', '{
 "file": "Policies.pdf",
 "id": "f95d4266-66cd-5b50-a01b-07a4dd66c501",
 "model": "multi-qa-MiniLM-L6-cos-v1",
 "rag_space_id": "knowledge-base",
 "result": "ok",
 "usage": {
 "prompt_tokens": 3803,
 "total_tokens": 3803
 }
}
Configure RAG Account [ RAG Account Name: "customer-support-rag-account" ; Endpoint: "https://myserver.example.com/llm/v1/" ; API key: Global::RAG_API_Key ; Verify SSL Certificates ]

Perform RAG Action [ RAG Account Name: "customer-support-rag-account" ; Space ID: "knowledge-base" ; Action: Add Data ; RAG Data: From File ; "Policies.pdf" ; Response Target: $ragAddResponse ]

Set Variable [ $id ; Value: JSONGetElement ( $ragAddResponse ; "id" ) ]
Set Variable [ $idType ; Value: JSONGetElementType ( $ragAddResponse ; "id" ) ]

Set Variable [ $idArrayToRemove ; Value:
 JSONSetElement ( "{}" ; "id" ;
 JSONSetElement ( "[]" ; 0 ; $id ; $idType ) ;
 JSONArray
 )
]

Perform RAG Action [ RAG Account Name: "customer-support-rag-account" ; Space ID: "knowledge-base" ; Action: Remove Data ; Parameters: $idArrayToRemove ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (668, 153, 'en', 3, 'Example 4 - Add documents with different chunk sizes', 'Adds both English and Japanese documentation to the same RAG space, using different chunk sizes optimized for each language.

The script uses a smaller chunk size (150 tokens) for the English technical documentation to enable precise retrieval of specific technical details.

For the Japanese regulatory documentation, the script uses a larger chunk size (300 tokens) because Japanese tokenization produces shorter text segments per token, requiring more tokens to preserve adequate context. The script also selects the Detect vertical text option to improve extraction of vertical text from this PDF file.', 'Configure RAG Account [ RAG Account Name: "product-docs-rag-account" ; Endpoint: "https://myserver.example.com/llm/v1/" ; API key: Global::RAG_API_Key ; Verify SSL Certificates ]

Perform RAG Action [ RAG Account Name: "product-docs-rag-account" ; Space ID: "product-knowledge" ; Action: Add Data ; RAG Data: From File ; "TechnicalSpecs_EN.pdf" ; Tokens per Text Chunk: 150 ]

Perform RAG Action [ RAG Account Name: "product-docs-rag-account" ; Space ID: "product-knowledge" ; Action: Add Data ; RAG Data: From File ; "Regulations_JA.pdf" ; Detect vertical text ; Tokens per Text Chunk: 300 ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (669, 153, 'en', 4, 'Example 5 - Add records as JSONL text', 'Adds FAQ records from a FileMaker table to a RAG space using JSONL format, where each line represents one complete FAQ record.

The script loops through the records in the FAQ table and builds a JSONL text string where each line is a JSON object containing the question ID, question, and answer. When this JSONL-formatted text is added to the RAG space, the AI model server automatically detects the format and treats each line (each FAQ record) as a separate semantic unit, preserving record boundaries and improving retrieval accuracy.', 'Configure RAG Account [ RAG Account Name: "customer-support-rag-account" ; Endpoint: "https://myserver.example.com/llm/v1/" ; API key: Global::RAG_API_Key ; Verify SSL Certificates ]

Set Variable [ $jsonlText ; Value: "" ]
Go to Layout [ "FAQ" (FAQ) ; Animation: None ]

Go to Record/Request/Page [ First ]
Loop [ Flush: Always ]
 Set Variable [ $jsonLine ; Value:
 JSONSetElement ( "{}" ;
 [ "id" ; FAQ::QuestionID ; JSONString ] ;
 [ "question" ; FAQ::Question ; JSONString ] ;
 [ "answer" ; FAQ::Answer ; JSONString ]
 )
 ]
 Set Variable [ $jsonlText ; Value: $jsonlText & $jsonLine & ¶ ]
 Go to Record/Request/Page [ Next ; Exit after last: On ]
End Loop

Perform RAG Action [ RAG Account Name: "customer-support-rag-account" ; Space ID: "knowledge-base" ; Action: Add Data ; RAG Data: From Text ; $jsonlText ; Response Target: $ragResponse ]
{"id":"001","question":"What is your return policy?","answer":"Items can be returned within 30 days..."}
{"id":"002","question":"How do I track my order?","answer":"You can track your order using the tracking number..."}
{"id":"003","question":"Do you ship internationally?","answer":"Yes, we ship to over 100 countries worldwide..."}');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (670, 154, 'en', 0, 'Example 1', 'Configures an AI account, goes to the Meeting Details layout, then in all records, performs a semantic find for Text (as natural language) in the Meetings::Note_Embedding container field, which contains embedding vectors for the contents of the Meetings::Note field (see Example 1 in Insert Embedding in Found Set). For more useful results, the return count is limited to 10 and the cosine similarity between Text and the contents of Meetings::Note_Embedding field must be greater than 0.4. The resulting found set is sorted with the most relevant records first.', 'Configure AI Account [ Account Name: "my-account" ; Model Provider: OpenAI ; API key: "sk-RZCtpWT..." ]

Go to Layout [ "Meeting Details" (Meetings) ; Animation: None ]

Perform Semantic Find [ Query by: Natural language ; Account Name: "my-account" ; Embedding Model: "text-embedding-3-small" ; Text: "Recruitment, job definition, training plan" ; Record set: All records ; Target field: Meetings::Note_Embedding ; Return count: 10 ; Cosine similarity condition: greater than ; Cosine similarity value: .4 ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (671, 154, 'en', 1, 'Example 2', 'Configures an AI account, goes to the Meeting Details layout, then asks the user for text to find. The GetEmbedding function sends that text to the model, then Set Field stores the embedding vectors in the global container field Meetings::Input. Assuming the Meetings::Note_Embedding container field contains embedding vectors for the Meetings::Note field''s contents (see Example 1 in Insert Embedding in Found Set), Perform Semantic Find compares the vector data in Meetings::Input with Meetings::Note_Embedding in all records and returns a found set that meets the return count and similarity criteria.', 'Configure AI Account [ Account Name: "my-account" ; Model Provider: OpenAI ; API key: "sk-RZCtpWT..." ]

Go to Layout [ "Meeting Details" (Meetings) ; Animation: None ]
Show Custom Dialog [ "Find meetings with notes about:" ; $Input ]

Set Field [ Meetings::Input ; GetEmbedding ( "my-account" ; "text-embedding-3-small" ; $Input ) ]

Perform Semantic Find [ Query by: Vector data ; Meetings::Input ; Record set: All records ; Target field: Meetings::Note_Embedding ; Return count: 10 ; Cosine similarity condition: greater than ; Cosine similarity value: .5 ; Save result: $$result]
[
 {
 "recordId" : "7",
 "similarity" : 0.999999947111836
 },
 {
 "recordId" : "1",
 "similarity" : 0.529809641529481
 },
 {
 "recordId" : "5",
 "similarity" : 0.524595621039394
 }
]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (672, 154, 'en', 2, 'Example 3', 'Searches a set of images for those that best match a text description. The script configures an AI account for Claris AI Model Server, goes to the Meeting Details layout, shows all records, then gets embedding vectors for the images in the Meetings::Image field using an image embedding model and stores them as binary data in the Meetings::Image_Embedding container field. Perform Semantic Find sends a natural language query text ("People sitting around a table") to a text embedding model using the same account, then compares the result with Meetings::Image_Embedding in all records and returns a found set that meets the similarity criteria.', 'Configure AI Account [ Account Name: "my-account" ; Model Provider: Custom ; Endpoint: "https://myserver.example.com/llm/v1/" ; Verify SSL Certificates ; API key: Global::API_Key ]

Go to Layout [ "Meeting Details" (Meetings) ; Animation: None ]
Show All Records

Insert Embedding in Found Set [ Account Name: "my-account" ; Embedding Model: "clip-ViT-B-32" ; Source Field: Meetings::Image ; Target Field: Meetings::Image_Embedding ]

Perform Semantic Find [ Query by: Natural language ; Account Name: "my-account" ; Embedding Model: "sentence-transformers/clip-ViT-B-32-multilingual-v1" ; Text: "People sitting around a table" ; Record set: All records ; Target field: Meetings::Image_Embedding ; Cosine similarity condition: greater than ; Cosine similarity value: .7 ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (673, 154, 'en', 3, 'Example 4', 'Searches a set of images for those that are most similar to the specified image. The script makes the same preparations as in the previous example, but in this example, Perform Semantic Find queries by the image in the Global::Temp_Image container field. Notice that the embedding model used for the query image is the same as the one that created embedding vectors for the images being searched. The script returns a found set that meets the similarity criteria.', 'Configure AI Account [ Account Name: "my-account" ; Model Provider: Custom ; Endpoint: "https://myserver.example.com/llm/v1/" ; Verify SSL Certificates ; API key: Global::API_Key ]

Go to Layout [ "Meeting Details" (Meetings) ; Animation: None ]
Show All Records

Insert Embedding in Found Set [ Account Name: "my-account" ; Embedding Model: "clip-ViT-B-32" ; Source Field: Meetings::Image ; Target Field: Meetings::Image_Embedding ]

Perform Semantic Find [ Query by: Image ; Account Name: "my-account" ; Embedding Model: "clip-ViT-B-32" ; Image: Global::Temp_Image ; Record set: All records ; Target field: Meetings::Image_Embedding ; Cosine similarity condition: greater than ; Cosine similarity value: .7 ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (674, 155, 'en', 0, 'Example 1', 'Configures an AI account, then uses the Perform SQL Query by Natural Language script step to ask a question about data in the Contacts table, which has data in Name and Company fields. The script step sends the schema for the Contacts table and the prompt "Which company does Alea work for?" to the model. The model generates the necessary SQL query and this script step executes it, then the model provides a natural language response stored in the Response field.', 'Configure AI Account [ Account Name: "my-account" ; Model Provider: OpenAI ; API key: "sk-..." ]

Perform SQL Query by Natural Language [ Account Name: "my-account" ; Model: Global::ModelName ; Prompt: "Which company does Alea work for?" ; Options specified: From list ; Action: Query ; Data Tables: From list ; Tables... ; Stream ; Response Target: Contacts::Response ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (675, 155, 'en', 1, 'Example 2', 'Asks the user for a question in a custom dialog—where the default button is "Query," button 2 is "Data Only," and button 3 is "Cancel"—and the question is stored in the $$UserPrompt variable. Then sets the $options variable to reflect the user''s choice for the action to perform: query or query for data only. If the user entered a question and didn''t click Cancel, runs the Perform SQL Query by Natural Language script step, passes in $$UserPrompt and $options, then returns the results from the model in $$QueryResultData, which is displayed in another custom dialog. Queries are limited to the Contacts and Employees tables.', 'Configure AI Account [ Account Name: "my-account" ; Model Provider: OpenAI ; API key: "sk-..." ]

Show Custom Dialog [ "Ask the database:" ; $$UserPrompt ]

Set Variable [ $options ; Value:
 Let ( [
 $choice = Get ( LastMessageChoice ) ;
 action_choice = Case (
 $choice = 1 ; "query" ;
 $choice = 2 ; "query for data only"
 )
 ] ;

 JSONSetElement (
 "";
 [ "action" ; action_choice ; JSONString ] ;
 [ "data tables" ; JSONMakeArray (
 "Contacts¶Employees" ;
 "¶" ;
 JSONString
 ) ;
 JSONArray ] ;
 [ "stream" ; "off" ; JSONString ]
 )
 )
]

If [ not IsEmpty ( $$UserPrompt ) and $choice ≠ 3 ]

 Perform SQL Query by Natural Language [ Account Name: "my-account" ; Model: Global::ModelName ; Prompt: $$UserPrompt ; Options specified: By JSON data ; Response Target: $$QueryResultData ]

 Show Custom Dialog [ "Data Result:" ; $$QueryResultData ]

End If');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (676, 155, 'en', 2, 'Example 3', 'Demonstrates using the Get SQL and Get DDL actions for debugging. The script first retrieves the DDL generated for the Products and Orders tables, then retrieves all SQL statements generated by the model for a specific prompt, storing each in separate variables for review.', 'Perform SQL Query by Natural Language [ Account Name: "my-account" ; Model: Global::ModelName ; Prompt: " " ; Options specified: From list ; Action: Get DDL ; Data Tables: By name ; "Products¶Orders" ; Response Target: $$ProductsOrdersDDL ]

Perform SQL Query by Natural Language [ Account Name: "my-account" ; Model: Global::ModelName ; Prompt: "Find the total value of orders for Product ID 101" ; Options specified: From list ; Action: Get SQL ; Data Tables: By name ; "Products¶Orders" ; Response Target: $$GeneratedSQL ]

Show Custom Dialog [ "Debugging Information" ; "Generated DDL:" & ¶ & $$ProductsOrdersDDL & ¶ & ¶ & "Generated SQL:" & ¶ & $$GeneratedSQL ]
CREATE TABLE "Products" (
"ProductID" int, /*Primary key that uniquely identifies a product*/
"ProductName" varchar(255), /*Descriptive name of the product*/
"Price" int, /*Price of the product in USD*/
PRIMARY KEY (ProductID)
);

CREATE TABLE "Orders" (
"OrderID" int, /*Primary key that uniquely identifies an order*/
"ProductID" int, /*Foreign key for a many-to-one relationship with Products table*/
"Quantity" int, /*Quantity of product in the order*/
PRIMARY KEY (OrderID),
FOREIGN KEY (ProductID) REFERENCES Products(ProductID)
);
SELECT SUM("Quantity" * "Price") AS "TotalValue" FROM "Orders" JOIN "Products" ON "Orders"."ProductID" = "Products"."ProductID" WHERE "Orders"."ProductID" = 101');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (677, 156, 'en', 0, 'Example 1', 'Turns on AI call logging in the ai-calls.log file in the Documents folder with verbose log entries, configures an AI account, goes to the Meeting Details layout, then uses the model to get embedding vectors for the text in the Meetings::Note field for the current record and stores it as text in the Meetings::Note_Embedding_Text text field. Logging remains enabled, so other scripts in this FileMaker Pro file can log AI calls as well.', 'Set AI Call Logging [ On ; Filename: "ai-calls.log" ; Verbose: On ; Truncate Messages: Off ]

Configure AI Account [ Account Name: "my-account" ; Model Provider: OpenAI ; API key: "sk-RZCtpWT..." ]

Go to Layout [ "Meeting Details" (Meetings) ; Animation: None ]

Insert Embedding [ Account Name: "my-account" ; Embedding Model: "text-embedding-3-small" ; Input: Meetings::Note ; Target: Meetings::Note_Embedding_Text ]');
