INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (686, 165, 'en', 0, 'Example 1 - Create a report with a cover page', 'Creates a new PDF file, adds a standard cover page, and saves the complete document.', 'Create PDF [ ]
Append PDF [ From: File ; "StandardCoverPage.pdf" ]
Close PDF [ Save to: File ; "Report.pdf" ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (687, 165, 'en', 1, 'Example 2 - Combine multiple PDF files', 'Goes to the first record in the Contracts layout, opens an existing PDF file in Global::CombinedPDF, appends the PDF file located in the Contracts::ContractPDF field in each record, then closes and saves the combined PDF file back to the CombinedPDF field.', 'Go to Layout [ "Contracts" (Contracts) ; Animation: None ]
Go to Record/Request/Page [ First ]

Open PDF [ From: Source ; Source: Global::CombinedPDF ]
Loop [ Flush: Always ]
 Append PDF [ From: Source ; Source: Contracts::ContractPDF ]
 Go to Record/Request/Page [ Next ; Exit after last: On ]
End Loop

Close PDF [ Save to: Target ; Target: Global::CombinedPDF ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (688, 165, 'en', 2, 'Example 3 - Append encrypted PDF file with password handling', 'Creates a PDF file in memory, then prompts the user for the password of the encrypted PDF file to append. If the PDF file is appended successfully, the current record is then appended and the PDF file is closed and saved to a file path. Otherwise, an error message is displayed and the PDF file in memory is discarded by saving it to a local variable, which is cleared when the script ends.', 'Set Error Capture [ On ]
Create PDF [ ]

Show Custom Dialog [ "Password for Confidential PDF" ; $inputPassword ]

Append PDF [ From: File ; "ConfidentialAppendix.pdf" ; Password: •••••••• ]
Set Variable [ $errorCode ; Value: Get ( LastError ) ]

If [ $errorCode ≠ 0 ]
 If [ $errorCode = 831 ]
 Show Custom Dialog [ "Authentication Failed" ; "Incorrect password for confidential document." ]
 Else If [ $errorCode = 832 ]
 Show Custom Dialog [ "Access Denied" ; "PDF security settings prevent copying." ]
 Else
 Show Custom Dialog [ "Error" ; "Couldn''t append document. Error code: " & $errorCode ]
 End If

 Close PDF [ Save to: Target ; Target: $discardPDF ]
 Exit Script [ Text Result: "Failed" ]
End If

Save Records as PDF [ Restore ; Save to: Currently open PDF ; Current record ]

Close PDF [ Save to: File ; "Declassified_Report.pdf" ; Create folders: Off ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (689, 166, 'en', 0, 'Example 1 - Cancel PDF on error', 'Creates a PDF report with error handling. If an error occurs while assembling the PDF file, the script closes the open PDF without saving it and notifies the user.', 'Set Error Capture [ On ]

Create PDF [ ]
If [ Get ( LastError ) ≠ 0 ]
 Show Custom Dialog [ "Error" ; "Couldn''t create PDF file." ]
 Exit Script [ Text Result: "Failed" ]
End If

Append PDF [ From: File ; "CoverPage.pdf" ]
If [ Get ( LastError ) ≠ 0 ]
 Cancel PDF
 Show Custom Dialog [ "Error" ; "Couldn''t add cover page to PDF file." ]
 Exit Script [ Text Result: "Failed" ]
End If

Save Records as PDF [ Restore ; Save to: Currently open PDF ; Records being browsed ]
If [ Get ( LastError ) ≠ 0 ]
 Cancel PDF
 Show Custom Dialog [ "Error" ; "Couldn''t add records to PDF file." ]
 Exit Script [ Text Result: "Failed" ]
End If

Close PDF [ Save to: File ; "Report.pdf" ; Create folders: Off ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (690, 167, 'en', 0, 'Example 1 - Save PDF to file', 'Creates a PDF file, adds pages for the current records, and saves it to Report.pdf in the user''s Documents folder.', 'Create PDF [ ]

Save Records as PDF [ Restore ; Save to: Currently open PDF ; Records being browsed ]

Set Variable [ $filePath ; Value: Get ( DocumentsPath ) & "Report.pdf" ]

Close PDF [ Save to: File ; $filePath ; Create folders: On ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (691, 167, 'en', 1, 'Example 2 - Save PDF file to container field', 'Creates a PDF report, stores it directly in a container field, and sets metadata fields for when it was generated and its type.', 'Create PDF [ ]

Append PDF [ From: Source ; Source: Global::CoverPage ]

Go to Layout [ "Monthly Report" (Reports) ]
Save Records as PDF [ Restore ; Save to: Currently open PDF ; Records being browsed ]

Close PDF [ Save to: Target ; Target: Global::GeneratedPDF ]

Set Field [ Global::GeneratedDate ; Get ( CurrentTimestamp ) ]
Set Field [ Global::ReportType ; "Monthly Summary" ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (692, 168, 'en', 0, 'Example 1 - Create a simple PDF document', 'Creates a PDF file, adds pages for the records currently being browsed, and saves it to the Documents folder.', 'Create PDF [ ]

Go to Layout [ "Contacts" (Contacts) ; Animation: None ]

Save Records as PDF [ Restore ; Save to: Currently open PDF ; Records being browsed ]

Set Variable [ $pdfFilePath ; Value: Get ( DocumentsPath ) & "Report.pdf" ]

Close PDF [ Save to: File ; $pdfFilePath ; Create folders: Off ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (693, 168, 'en', 1, 'Example 2 - Create a multi-section PDF report', 'Creates an encrypted PDF report by combining a cover page, multiple data sections, and a summary page. Create PDF uses Specify options to set a password to open the file.', 'Create PDF [ Restore ]

Append PDF [ Source: File ; "CoverPage.pdf" ]

Go to Layout [ "Orders" (Orders) ]
Save Records as PDF [ Restore ; Save to: Currently open PDF ; Records being browsed ]

Go to Layout [ "Customers" (Customers) ]
Save Records as PDF [ Restore ; Save to: Currently open PDF ; Records being browsed ]

Append PDF [ From: Source ; Global::SummaryPage ]

Set Variable [ $pdfFilePath ; Value: Get ( DocumentsPath ) & "Complete_Report_" & Year ( Get ( CurrentDate ) ) & ".pdf" ]

Close PDF [ Save to: File ; $pdfFilePath ; Create folders: Off ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (694, 168, 'en', 2, 'Example 3 - Create PDF with error handling', 'Creates a PDF report with error handling to ensure the PDF file is closed if an error occurs. Notice that after a failed attempt to modify the PDF file, the PDF file is closed without saving by the Cancel PDF script step.', 'Set Error Capture [ On ]

Create PDF [ ]
Set Variable [ $errorCode ; Value: Get ( LastError ) ]
If [ $errorCode ≠ 0 ]
 Show Custom Dialog [ "Error" ; "Couldn''t create PDF: " & $errorCode ]
 Exit Script [ Text Result: "Failed" ]
End If

Append PDF [ From: File ; "CoverPage.pdf ]
Set Variable [ $errorCode ; Value: Get ( LastError ) ]
If [ $errorCode ≠ 0 ]
 Cancel PDF
 Show Custom Dialog [ "Error" ; "Could not add cover page: " & $errorCode ]
 Exit Script [ Text Result: "Failed" ]
End If

Save Records as PDF [ Restore ; Save to: Currently open PDF ; Records being browsed ]
Set Variable [ $errorCode ; Value: Get(LastError) ]
If [ $errorCode ≠ 0 ]
 Cancel PDF
 Show Custom Dialog [ "Error" ; "Could not add records: " & $errorCode ]
 Exit Script [ Text Result: "Failed" ]
End If

Close PDF [ Save to: File ; "Report.pdf" ; Create folders: Off ]
Set Variable [ $errorCode ; Value: Get ( LastError ) ]
If [ $errorCode = 0 ]
 Show Custom Dialog [ "Success" ; "PDF created successfully" ]
Else
 Show Custom Dialog [ "Error" ; "Could not save PDF: " & $errorCode ]
End If');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (695, 169, 'en', 0, 'Example 1 - Open and modify an existing PDF file', 'Opens an existing PDF file in the current directory using a path and filename of image:ExistingReport.pdf, adds the current record, and saves the modified version to image:UpdatedReport.pdf.', 'Open PDF [ From: File ; Source file: "ExistingReport.pdf" ]

Save Records as PDF [ Restore ; Save to: Currently open PDF ; Current record ]

Close PDF [ Save to: File ; "UpdatedReport.pdf" ; Create folders: Off ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (696, 169, 'en', 1, 'Example 2 - Open encrypted PDF file with password', 'Opens a password-protected PDF file stored in a container field, appends the pages from another PDF file, and saves the result to a global variable with the filename UpdatedContract.pdf.', 'Go to Layout [ "Contracts" (Contracts) ; Animation: None ]

Open PDF [ From: Source ; Source: Contracts::ContractPDF ; Password: •••••••• ]

Append PDF [ From: File ; Source file: "Appendix.pdf" ]

Close PDF [ Save to: Target ; Target: $$modifiedPDF ; Filename: "UpdatedContract.pdf" ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (697, 169, 'en', 2, 'Example 3 - Open PDF file with error handling', 'Opens a PDF file, then handles errors using a calculation to map error codes to user-friendly messages and the Cancel PDF script step to close the open PDF without saving it.', 'Set Error Capture [ On ]

Go to Layout [ "Contracts" (Contracts) ; Animation: None ]

Set Variable [ $pdfFilePath ; Value: "image:Contract.pdf" ]

Open PDF [ From: File ; Source file: $pdfFilePath ; Password: •••••••• ]

Set Variable [ $errorCode ; Value: Get(LastError) ]

Set Variable [ $errorMessage ; Value:
 Case (
 $errorCode = 0 ; "" ;
 $errorCode = 830 ; "PDF file not found or has an invalid format." ;
 $errorCode = 831 ; "Incorrect password for encrypted PDF file." ;
 $errorCode = 832 ; "PDF file security settings prevent modification." ;
 $errorCode = 833 ; "Another PDF file is already open. Close it first." ;
 "Unknown error opening PDF: " & $errorCode
 )
]

If [ $errorCode ≠ 0 ]
 Cancel PDF
 Show Custom Dialog [ "PDF Error" ; $errorMessage ]
 Exit Script [ Text Result: "Failed" ]
End If

Append PDF [ From: Source ; Source: Contracts::ContractPDF ]

Close PDF [ Save to: File ; $pdfFilePath ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (698, 170, 'en', 0, 'Example 1 - Print PDF file with dialog', 'Prints a PDF file from a container field, showing the Print dialog to allow the user to specify print settings.', 'Print PDF [ From: Source ; Source: Documents::ReportPDF ; With dialog: On ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (699, 170, 'en', 1, 'Example 2 - Automated printing with saved settings', 'Goes to the first record in the Contracts layout. If $$printSettings hasn''t already been set, the script prints the PDF file in the Contracts::ContractPDF container field file, displaying the Print dialog so the user can choose the print settings. The settings are saved in the $$printSettings variable. If $$printSettings is already set, the PDF in the first record is print using the saved settings. Then the script loops through the remaining records, printing the PDF file using the same print settings.', 'Go to Layout [ "Contracts" (Contracts) ; Animation: None ]
Go to Record/Request/Page [ First ]

If [ IsEmpty ( $$printSettings ) ]
 Print PDF [ From: Source ; Source: Contracts::ContractPDF ; Save print options to: $$printSettings ; With dialog: On ]
Else
 Print PDF [ From: Source ; Source: Contracts::ContractPDF ; Restore: Use print options from: $$printSettings ]
End If
Go to Record/Request/Page [ Next ; Exit after last: On ]

Loop [ Flush: Always ]
 Print PDF [ From: Source ; Source: Contracts::ContractPDF ; Restore: Use print options from: $$printSettings ]
 Go to Record/Request/Page [ Next ; Exit after last: On ]
End Loop');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (700, 171, 'en', 0, 'Example 1 - Save current records to new PDF file', 'Goes to the Products layout, shows all records, sorts the records, and saves the records as a PDF without prompting the user.', 'Go to Layout [ "Products" (Products) ; Animation: None ]
