INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (701, 171, 'en', 1, 'Example 2 - Save records to new PDF file then append related records', 'Finds all invoices with the current record''s Customer ID, sorts, saves the invoices to a PDF, and appends the products purchased by the customer to the PDF.', 'Go to Layout [ "Invoices" (Invoices) ; Animation: None ]
Find Matching Records [ Replace ; Invoices::Customer ID ]
Sort Records [ Restore ; With dialog: Off ]

Save Records as PDF [ Restore ; Save to: File ; "Customer Backup.pdf" ; Create folders: Off ; With dialog: Off ; Records being browsed ]

Go to Related Record [ Show only related records ; Match found set ; From table: "Products" ; Using layout: "Products" (Products) ]

Save Records as PDF [ Restore ; Save to: File ; Append ; "Customer Backup.pdf" ; Create folders: Off ; With dialog: Off ; Records being browsed ]

Go to Layout [ original layout ; Animation: None ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (702, 171, 'en', 2, 'Example 3 - Create a PDF report and add multiple sections', 'Creates a comprehensive report by building a PDF in memory, adding multiple sections from different layouts, then saving the complete document to a file path.', 'Create PDF [ ]

