INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (717, 186, 'en', 0, 'Example 1', 'Displays a custom dialog box that asks if the user wants to share the current database, and opens the FileMaker Network Settings dialog box.', 'Show Custom Dialog ["Do you want to share this database?"]
