Allow Formatting Bar [ On ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (721, 190, 'en', 0, 'Example 1', 'Plays a media file in full screen and hides playback controls after the OnRecordLoad script trigger is activated:', 'AVPlayer Play [Field: Library::Video; Presentation: Full Screen Only; Hide Controls: Yes]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (722, 190, 'en', 1, 'Example 2', 'Resumes playing a media file from the position at which it was last stopped.', 'Set Field [Library::Last Stopped Position; GetAVPlayerAttribute ("position")]
AVPlayer Play [Field: Library::Video; Position: Library::Last Stopped Position]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (723, 190, 'en', 2, 'Example 3', 'Plays the media file in full screen for iPhone, and embedded for iPad.', 'If [Get(Device) = 3 //iPad]
 AVPlayer Play [Object Name: "Container"; Presentation: Start Embedded]
Else If [Get(Device) = 4 //iPhone]
 AVPlayer Play [Object Name: "Container"; Presentation: Start Full Screen]
End If');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (724, 191, 'en', 0, 'Example 1', 'Changes the setting of a video that is currently playing to start the playback 50 seconds from the beginning of the file. The video is stretched to fill the playback area without preserving the aspect ratio.', 'AVPlayer Set Options [Position: 50; Zoom: Stretch]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (725, 191, 'en', 1, 'Example 2', 'Enables user interaction with the playback after the video has played for 30 seconds.', 'AVPlayer Play [Object Name: "Container"; Disable Interaction: Yes]
Pause/Resume Script [Duration (seconds): 30]
AVPlayer Set Options [Disable Interaction: No]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (726, 191, 'en', 2, 'Example 3', 'Pauses the audio file that is playing if FileMaker Go moves to the background.', 'AVPlayer Set Options [Pause in Background: Yes]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (727, 192, 'en', 0, 'Example 1', 'Resumes playing a media file that has been paused.', 'AVPlayer Set Playback State [Playing]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (728, 192, 'en', 1, 'Example 2', 'Stops a media file if it is playing.', 'If [GetAVPlayerAttribute("playbackState") = 1
