End If');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (729, 193, 'en', 0, 'Example 1', 'Performs a find. If no records were found, beeps.', 'Set Error Capture [On]
