 Beep
 Show Custom Dialog ["No records were found."]
End If');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (730, 194, 'en', 0, 'Example 1', 'Dials the phone number contained in the script.', 'Dial Phone [With dialog: On; "5550987654"]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (731, 194, 'en', 1, 'Example 2', 'Dials the phone number contained in the Work Phone field in the current record.', 'Go to Layout ["Customer Details"]
If [not IsEmpty ( Customers::Work Phone )]
 Dial Phone [With dialog: Off; Customers::Work Phone]
End If');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (732, 194, 'en', 2, 'Example 3', 'Filters the contents of the Work Phone field for appropriate characters and dials the filtered number.', 'Go to Layout ["Customer Details"]
