INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (733, 195, 'en', 0, 'Example 1', 'In FileMaker Go, enables the touch keyboard.', 'Enable Touch Keyboard [On]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (734, 195, 'en', 1, 'Example 2', 'Checks the current setting of the touch keyboard and disables the touch keyboard if it is enabled.', 'If [ Get ( TouchKeyboardState ) = 1]
 Enable Touch Keyboard [Off]
End If');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (735, 196, 'en', 0, 'Example 1', 'Returns metadata for all table occurrences by specifying no value for the tables key. In this case, there''s one source (or base) table (Products) and two table occurrences (Products and Products_InStock). This example uses the JSONSetElement function to create the JSON object in the Request option.', 'Execute FileMaker Data API [ Select ; Target: $$result ;
JSONSetElement ( "{}" ;
 [ "action" ; "metaData" ; JSONString ] ;
 [ "tables" ; "" ; JSONString ]
) ]
Set Variable [ $$result ; JSONFormatElements ( $$result ) ]
{
 "messages" :
 [
 {
 "code" : "0",
 "message" : "OK"
 }
 ],
 "response" :
 {
 "tables" :
 [
 {
 "baseTable" : "Products",
 "name" : "Products"
 },
 {
 "baseTable" : "Products",
 "name" : "Products_InStock"
 }
 ]
 }
}');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (736, 196, 'en', 1, 'Example 2', 'Based on the Products layout, returns the first record in the table associated with the Products layout.', 'Execute FileMaker Data API [ Select ; Target: $$result ;
JSONSetElement ( "{}" ;
 [ "layouts" ; "Products" ; JSONString ] ;
 [ "limit" ; 1 ; JSONNumber ]
) ]
Set Variable [ $$result ; JSONFormatElements ( $$result ) ]
{
 "messages" :
 [
 {
 "code" : "0",
 "message" : "OK"
 }
 ],
 "response" :
 {
 "data" :
 [
 {
 "fieldData" :
 {
 "ID" : "FB1",
 "Name" : "Donuts",
 "Stock" : 43
 },
 "modId" : "6",
 "portalData" : {},
 "recordId" : "1"
 }
 ],
 "dataInfo" :
 {
 "database" : "Favorite Bakery",
 "foundCount" : 3,
 "layout" : "Products",
 "returnedCount" : 1,
 "table" : "Products",
 "totalRecordCount" : 3
 }
 }
}');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (737, 196, 'en', 2, 'Example 3', 'Based on the Products layout, performs a find for records where the Stock field is less than 40, and returns the found set sorted by the Stock field in descending order.', 'Execute FileMaker Data API [ Select ; Target: $$result ;
