 }
 }
}');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (738, 196, 'en', 3, 'Example 4', 'Based on the Products layout, returns the first record in the table associated with the Products layout and if there are portal rows, return the first 2 records after the skipping the first 2.', 'Execute FileMaker Data API [ Select ; Target: $$result ;
