INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (739, 196, 'en', 4, 'Example 5', 'Based on the Products layout, modifies the record specified by recordId, updating the values of the Stock and Name fields.', 'Execute FileMaker Data API [ Select ; Target: $$result ;
