INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (740, 196, 'en', 5, 'Example 6', 'Based on the Products layout, creates a record and sets the values of the Stock, ID, and Name fields. Because the ID field is set to auto-enter a serial number and the Prohibit modification of value during data entry option is enabled, setting the prohibitmode key to script in the options object overrides that auto-enter requirement and sets the ID field as specified.', 'Execute FileMaker Data API [ Select ; Target: $$result ;
 JSONSetElement ( "{}" ;
 [ "action" ; "create" ; JSONString ] ;
 [ "layouts" ; "Products" ; JSONString ] ;
 [ "options" ; "{ \"prohibitmode\" : \"script\" }" ; JSONObject ] ;
 [ "fieldData" ; "{ \"Stock\" : 14 ,
 \"ID\" : \"FB42\" ,
 \"Name\" : \"Croissants\" }" ; JSONObject ]
 ) ]
 Set Variable [ $$result ; JSONFormatElements ( $$result ) ]
{
 "messages" :
 [
 {
 "code" : "0",
 "message" : "OK"
 }
 ],
 "response" :
 {
