 "recordId" : "7"
 }
 }');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (741, 197, 'en', 0, 'Example 1', 'Updates records in the Employees table of an external ODBC data source.', 'Execute SQL [With dialog: On; SQL Text: INSERT INTO Employees (EmployeeID, FirstName, LastName, Title, WorkPhone, Salary) VALUES (100, N''Joe'', N''Smith'', N''Software Engineer'', ''987-7000'', 100000) UPDATE Employees SET Title = N''Manager'' WHERE EmployeeID = 103 DELETE FROM Employees WHERE EmployeeID = 103]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (742, 197, 'en', 1, 'Example 2', 'Calculates and performs an SQL statement to update records in the Customers table of an external ODBC data source.', 'Execute SQL [With dialog: On; Calculated SQL Text: "INSERT INTO Customers (Company, LastName) VALUES (" & Customers::Company & "," & "N''" & Customers::Last & "'')"]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (743, 198, 'en', 0, 'Example 1', 'Prevents the user from opening the database on a weekend. Started by the OnFirstWindowOpen script trigger.', 'Allow User Abort [Off]
