End If');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (744, 199, 'en', 0, 'Example 1', 'Assigns serial numbers to all records in the found set and flushes the changes to the disk.', 'Perform Find [Restore]
