INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (745, 200, 'en', 0, 'Example 1', 'Clears all web viewer cookies before prompting the next FileMaker user to sign in, preventing them from accessing the previous user''s authenticated web sessions.', 'Flush Web Viewer Cookies
Re-Login [ With dialog: On ; Current File ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (746, 200, 'en', 1, 'Example 2', 'When a user needs to switch accounts in a web-based service displayed in a web viewer with the object name WebViewer_OAuth, flushes cookies to force the web service to prompt for new credentials.', 'Flush Web Viewer Cookies
Refresh Object [ Object Name: "WebViewer_OAuth" ; Repetition: 1 ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (747, 200, 'en', 2, 'Example 3', 'Provides users with a way to manually clear all web viewer session data for privacy or compliance requirements.', 'Show Custom Dialog [ "Clear Session Data?" ; "This will sign you out of all web services in web viewers." ]
If [ Get ( LastMessageChoice ) = 1 ]
 Flush Web Viewer Cookies
 Show Custom Dialog [ "Session Cleared" ; "All web viewer sessions have been cleared." ]
End If');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (748, 201, 'en', 0, 'Example 1', 'Opens a folder selection dialog box that displays the desktop, prompts the user to select the Pictures folder, then sets Products::Pictures Folder to the path of the selected folder.', 'Get Folder Path [$FOLDER; "Select the Pictures folder"; Get(DesktopPath)]
Set Field [Products::Pictures Folder; $FOLDER]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (749, 201, 'en', 1, 'Example 2', 'Performs a find, prompts the user to select a folder to export to, then loops through records to export files that are in the Products::Picture field.', 'Perform Find [Restore]
Get Folder Path [Allow Folder Creation; $FOLDER; "Export to Folder"]
Loop [ Flush: Always ]
 Set Variable [$PATH; Value:$FOLDER & Products::Picture]
 Export Field Contents [Products::Picture; $PATH ; Create folders: Off]
 Go to Record/Request/Page [Next; Exit after last: On]
End Loop');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (750, 202, 'en', 0, 'Example 1', 'Goes to the Invoice Details layout and installs the Invoices Menu Set if the Print Invoices Menu Set was installed.', 'Go to Layout ["Invoice Details"]
If [Get ( CustomMenuSetName ) = "Print Invoices Menu Set"]
 Install Menu Set ["Invoices Menu Set" ; Use as file default: Off]
End If');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (751, 203, 'en', 0, 'Example 1', 'Installs the Video plug-in.', 'Show Custom Dialog ["Do you want to install the latest version of the Video Plug-In?"]
If [Get ( LastMessageChoice ) = 1]
 Install Plug-In File[Plugins::Video]
End If');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (752, 203, 'en', 1, 'Example 2', 'Installs a plug-in from the appropriate container field based on the operating system and hardware architecture of the system where this script is run.', 'Set Variable [ $plugin_json ; Value: Get ( InstalledFMPluginsAsJSON ) ]
Set Variable [ $arch ; Value: JSONGetElement ( $plugin_json ; "environment.architecture" ) ]
Set Variable [ $platform ; Value: GetAsNumber ( JSONGetElement ( $plugin_json ; "environment.platform" ) ) ]

# macOS
If [ $platform = 1 ]
 If [ $arch = "arm64" ]
 # Apple silicon
 Install Plug-In File [ Plugins::macOS_Universal ]
 Else If [ $arch = "x86_64" and IsEmpty ( Plugins::macOS_Universal ) ]
 # Intel and no Universal plug-in available
 Install Plug-In File [ Plugins::macOS_Intel ]
 Else
 # Intel and Universal plug-in available
 Install Plug-In File [ Plugins::macOS_Universal ]
 End If
 Exit Script [ Text Result: "Plug-in for macOS installed" ]
End If

# Windows
If [ $platform = -2 ]
 Install Plug-In File [ Plugins::Windows_64bit ]
 Exit Script [ Text Result: "Plug-in for Windows installed" ]
End If

# Linux
If [ $platform = 5 ]
 If [ PatternCount ( Get ( HostApplicationVersion ) ; "Cloud Server 2" ) > 0 ]
 Else
 Install Plug-In File [ Plugins::Linux ]
 Exit Script [ Text Result: "Plug-in for Linux installed" ]
 End If
End If

Show Custom Dialog [ "Plug-ins are not supported on this platform." ]');
