INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (770, 212, 'en', 0, 'Example 1', 'Goes to the Customers layout, performs a find, and sends a prewritten email to the address in the Email field in the current record without prompting the user.', 'Go to Layout ["Customers"]
