INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (771, 212, 'en', 1, 'Example 2', 'Saves the current record as a PDF, then emails the PDF to the address in the Email field in the current record.', 'Go to Layout ["Print Invoices"]
Save Records as PDF [Restore; With dialog: Off; "Invoice.pdf"; Current record ; Create folders: Off]
Send Mail [Send via E-mail Client; With dialog: Off; To: Customers::Email; Subject: Invoices::Summary; Message: "Dear Customer,¶¶Thank you for your business. Your invoice is attached."; "Invoice.pdf"]
Go to Layout [original layout]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (772, 213, 'en', 0, 'Example 1', 'For a student survey, prompts users to enter their student ID, uses a custom function (IsStudentIDValid) to check that the student ID is valid, then sets the session identifier to the student ID.', 'Set Field [ Survey::StudentID ; "" ]
Show Custom Dialog [ Message: "Enter your student ID number." ; Survey::StudentID ]
If [ IsStudentIDValid ( Survey::StudentID ) ]
 Set Session Identifier [ Survey::StudentID ]
Else
 Show Custom Dialog [ "A valid student ID is required." ]
 Exit Script [ Result: "A valid student ID was not provided." ]
End If');
