INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (775, 214, 'en', 2, 'Example 3', 'Displays the URL entered in the Website field in the Product Website web viewer:', 'Set Web Viewer [Object Name: "Product Website"; URL: Products::Website]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (776, 214, 'en', 3, 'Example 4', 'Uses the data URL scheme to display a small icon in a web viewer named WV2.', 'Set Web Viewer [Object Name: "WV2"; URL: "data:image/gif;base64,R0lGODlhFwAMAKEAAL+/v///AAAAUwAAACH5BAEAAAAALAAAAAAXAAwAAAI7hBGHapHcXJKPumizpigI+QliSH0XIjokWJ6oB4+qt0Zmaqpjesxz7st1YD8ZEbhJajAuDgfSYTx60wIAOw=="]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (777, 215, 'en', 0, 'Example 1', 'Performs a find. If no records were found, displays a custom dialog box.', 'Perform Find [Restore]
If [Get (FoundCount) = 0]
 Show Custom Dialog ["No records were found."]
End If');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (778, 215, 'en', 1, 'Example 2', 'Displays a custom dialog at a specified size in the center of the current window.', 'Set Variable [ $height ; Value: 200 ]
Set Variable [ $width ; Value: 400 ]
Show Custom Dialog [ Message: "Message in the center of the current window" ; Height: $height ; Width: $width ; Top: Get ( WindowTop ) + ( Get ( WindowHeight ) - $height ) / 2 ; Left: Get ( WindowLeft ) + ( Get ( WindowWidth ) - $width ) / 2 ]');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (779, 215, 'en', 2, 'Example 3', 'Creates a new record, prompts the user to enter information, then goes to the Customer Details layout. The first button is Cancel so that users don''t inadvertently create a record by pressing Return or Enter in the custom dialog box.', 'Freeze Window
New Record/Request
Show Custom Dialog ["New Customer"; "Enter information into the fields below:"; Customers::Company; Customers::Name; Customers::City]
If [Get ( LastMessageChoice ) = 1]
 Delete Record/Request [With dialog: Off]
Else
 Go to Layout ["Customer Details"]
End If');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (780, 215, 'en', 3, 'Example 4', 'Enters Find mode, prompts the user for find criteria, and performs the find. If the find returns no records, asks if the user wants to find again, and either performs the script again or halts all scripts.

Script: Find', 'Enter Find Mode [Pause: Off]
Show Custom Dialog ["Find customers by ID, name, or city."; Customers::ID; Customers::Name; Customers::City]
If [Get ( LastMessageChoice ) = 1]
 Perform Find [ ]
 If [Get ( FoundCount ) = 0]
 Show Custom Dialog ["No records were found. Find again?"]
 If [Get ( LastMessageChoice ) = 1]
 #Calls this script as a sub-script
 Perform Script [Specified: From list ; "Find" ; Parameter: ]
 Else
 Show All Records
 #Halts all scripts and sub-scripts
 Halt Script
 End If
 End If
Else If [Get ( LastMessageChoice ) = 2]
 Enter Browse Mode [Pause: Off]
End If');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (781, 216, 'en', 0, 'Example 1', 'Tells the user to enter a company name if the Company field is empty. Can be started by the OnRecordCommit script trigger, OnLayoutExit script trigger, OnWindowClose script trigger, or OnWindowTransaction script trigger.', 'If [IsEmpty ( Contacts::Company )]
 Speak ["Enter a company name"]
End If');
INSERT INTO "step_examples" ("id", "script_step_id", "locale", "position", "title", "description", "body") VALUES (782, 216, 'en', 1, 'Example 2', 'Speaks the contents of the Summary field in the current record.', 'Go to Layout ["Invoice Details"]
Speak [Invoices::Summary]');
